/* Tako Desktop — padrão Apple TV com material Liquid Glass (imagem de referência + skill apple-design).
   A arte do jogo fica NÍTIDA; só o que está atrás do vidro é desfocado (backdrop-filter nas prévias).
   No Slint: cópia da arte desfocada uma vez ao decodificar, desenhada só dentro dos painéis. */

/* Arte do jogo de exemplo (Hades II, arte da Supergiant Games enviada pelo mantenedor como referência), nítida.
   .dk-art-azul troca para uma arte de teste azul, usada para validar o vidro sobre arte fria/escura. */
:root { --accent: #1f5a4e; --art-img: url("data:image/jpeg;base64,"); }

.dk-stage { box-sizing: border-box; min-height: 100vh; margin: 0; padding: 28px; color: var(--on-accent); font-family: var(--font-text);
  display: flex; flex-wrap: wrap; align-items: center; gap: 16px; font-size: 15px; position: relative; overflow: hidden;
  background: var(--canvas); }
.dk-stage.dk-col { flex-direction: column; align-items: stretch; }
.dk-stage * { box-sizing: border-box; }

/* Arte do jogo nítida na janela inteira + escurecimentos só onde há texto direto sobre ela */
.dk-stage.dk-art-azul { --accent: #1c3d73; --art-img: url("data:image/jpeg;base64,"); }
/* Componentes soltos: fundo neutro escuro com um brilho suave da cor do jogo, só para o vidro ter o que mostrar. */
.dk-art { position: absolute; inset: 0; z-index: 0;
  background: radial-gradient(60% 90% at 75% 30%, color-mix(in srgb, var(--accent) 55%, transparent), transparent 70%),
    radial-gradient(40% 70% at 20% 90%, #ffffff0d, transparent 70%), var(--canvas); }
/* Telas e Destaque: a arte do jogo. Na janela inteira ela vai para a direita para não ficar atrás do título. */
.dk-com-arte .dk-art { background: var(--art-img) center 25% / cover no-repeat, var(--canvas); }
.dk-tela .dk-art { background: var(--art-img) left 200px top 0 / auto 100% no-repeat, var(--canvas); }
/* Bordas da janela: a mesma arte desfocada, misturada com a cor do jogo, entra pela direita (e pela esquerda, atrás da lista)
   e se funde com a arte nítida. No Slint é a mesma cópia desfocada do vidro, sem custo extra. */
.dk-tela .dk-art::before { content: ""; position: absolute; inset: -60px; z-index: 0;
  background: linear-gradient(color-mix(in srgb, var(--accent) 45%, transparent), color-mix(in srgb, var(--accent) 45%, transparent)),
    var(--art-img) left 260px top 60px / auto 100% no-repeat, var(--canvas);
  filter: blur(42px) saturate(1.35);
  -webkit-mask-image: linear-gradient(90deg, #000 0%, #000 12%, transparent 30%, transparent 62%, #000 92%);
          mask-image: linear-gradient(90deg, #000 0%, #000 12%, transparent 30%, transparent 62%, #000 92%); }
.dk-art::after { z-index: 1; }
.dk-art-azul .dk-art { background-position: center; background-size: cover; }
.dk-art::after { content: ""; position: absolute; inset: 0;
  /* Sem faixa vertical: o escurecimento lateral só desce (nunca sobe nem fica parado no meio) e o forte fica atrás do texto,
     numa elipse ancorada embaixo à esquerda. Uma faixa escura entre 27% e 50% virava "sombra no meio" sobre arte clara. */
  background:
    radial-gradient(52% 64% at 24% 90%, var(--art-scrim-left) 0%, #0b0b0e66 55%, #0b0b0e00 100%),
    linear-gradient(90deg, #0b0b0e59 0%, #0b0b0e52 22%, #0b0b0e38 40%, #0b0b0e14 56%, #0b0b0e00 72%),
    linear-gradient(0deg, var(--art-scrim-bottom) 0%, #0b0b0e00 40%); }
.dk-stage > *:not(.dk-art) { position: relative; z-index: 1; }

.dk-icon { width: 20px; height: 20px; flex: none; display: block; }

/* Material */
/* Liquid Glass: lente desfocada e saturada, tinta adaptativa, brilho de cima, reflexo especular na borda.
   Vidro só sobre a arte. Dentro de um vidro, os controles são preenchimentos (glass-control), nunca outro vidro. */
.dk-glass, .dk-btn, .dk-badge {
  position: relative; isolation: isolate; border: 0 !important;
  background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px),
    radial-gradient(560px 380px at 0 0, color-mix(in srgb, var(--accent) 16%, transparent), transparent 75%), var(--glass-panel);
  transition: background-color var(--tempo-cor), box-shadow var(--tempo-hover);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  box-shadow: inset 0 0 0 1px var(--glass-edge), inset 0 -1px 0 #ffffff0d, var(--shadow-float); }
.dk-glass::before, .dk-btn::before, .dk-badge::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none;
  background: linear-gradient(170deg, var(--glass-specular) 0%, #ffffff1a 18%, #ffffff00 40%, #ffffff00 80%, #ffffff0d 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); }
.dk-glass.dk-dense { background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px),
    radial-gradient(560px 380px at 0 0, color-mix(in srgb, var(--accent) 16%, transparent), transparent 75%), var(--glass-panel-dense); }
.dk-btn.dk-hover { background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px), linear-gradient(var(--glass-hover), var(--glass-hover)), var(--glass-panel); }
.dk-btn.dk-pressed { background: linear-gradient(var(--glass-pressed), var(--glass-pressed)), var(--glass-panel); }
.dk-btn.dk-danger { background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px), var(--glass-panel-dense); }
.dk-btn.dk-disabled { opacity: 1; color: var(--on-accent-subtle); }
.dk-btn.dk-disabled .dk-icon { opacity: .7; }
/* Dentro de um vidro (barra, painel, cartão, camada), o botão é preenchimento — nunca vidro sobre vidro. */
.dk-glass .dk-btn, .dk-dialog .dk-btn, .dk-panel-side .dk-btn, .dk-menu .dk-btn, .dk-toast .dk-btn {
  background: var(--glass-control); backdrop-filter: none; -webkit-backdrop-filter: none; box-shadow: inset 0 0 0 1px var(--glass-edge); }
.dk-glass .dk-btn::before, .dk-dialog .dk-btn::before, .dk-panel-side .dk-btn::before, .dk-menu .dk-btn::before, .dk-toast .dk-btn::before { display: none; }
.dk-glass .dk-btn.dk-hover, .dk-dialog .dk-btn.dk-hover, .dk-panel-side .dk-btn.dk-hover { background: var(--glass-hover); }
.dk-glass .dk-btn.dk-pressed, .dk-dialog .dk-btn.dk-pressed, .dk-panel-side .dk-btn.dk-pressed { background: var(--glass-pressed); }
/* O Trailer é a exceção: o botão fica sobre a miniatura (imagem), então é vidro. */
.dk-glass.dk-trailer .dk-btn { background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px), var(--glass-panel);
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate)); -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  box-shadow: inset 0 0 0 1px var(--glass-edge), var(--shadow-float); }
.dk-glass.dk-trailer .dk-btn::before { display: block; }

/* Barra superior flutuante */
.dk-top { height: var(--topbar-height); width: 100%; padding: 0 12px 0 20px; border-radius: var(--radius-card);
  display: flex; align-items: center; gap: 12px; }
.dk-brand { display: flex; align-items: center; gap: 10px; margin-right: 28px; }
.dk-brand img { width: 30px; height: 30px; }
.dk-brand span { font: 700 22px/1 var(--font-title); letter-spacing: -.01em; }
.dk-seg { display: flex; gap: 4px; padding: 4px; border-radius: var(--radius-full); background: var(--glass-control); border: 1px solid var(--glass-edge); }
.dk-nav { height: 40px; padding: 0 18px; border-radius: var(--radius-full); display: inline-flex; align-items: center; gap: 10px;
  color: var(--on-accent-muted); font: 500 15px/1 var(--font-text); white-space: nowrap; }
.dk-nav.dk-current { background: linear-gradient(180deg, var(--glass-item-highlight) 0%, #ffffff0a 60%), var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge), inset 0 1px 0 #ffffff33; color: var(--on-accent); font-weight: 600; }
.dk-nav.dk-hover { background: var(--glass-hover); color: var(--on-accent); }
.dk-spacer { flex: 1; }

/* Botões */
.dk-btn { height: var(--control-height); padding: 0 18px; border-radius: var(--radius-full); 
  display: inline-flex; align-items: center; justify-content: center; gap: 10px; white-space: nowrap;
   color: var(--on-accent); font: 600 15px/1 var(--font-text); }
.dk-btn.dk-pressed { transform: scale(var(--escala-pressionado)); }
.dk-btn.dk-round { width: 52px; height: 52px; padding: 0; }
.dk-btn.dk-round .dk-icon { width: 22px; height: 22px; }
.dk-btn.dk-on { color: var(--warning); }
.dk-btn.dk-danger { color: var(--error); }
.dk-play { height: var(--primary-height); min-width: 232px; padding: 0 32px; border-radius: var(--radius-full); border: 0;
  display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  background: linear-gradient(180deg, var(--primary-top) 0%, var(--primary-bottom) 100%); color: var(--on-primary);
  font: 700 19px/1 var(--font-text); box-shadow: inset 0 1px 0 #ffffff, var(--shadow-float); }
.dk-play .dk-icon { width: 22px; height: 22px; }
.dk-play.dk-pressed { transform: scale(var(--escala-pressionado)); filter: brightness(.94); }
.dk-play.dk-loading { color: #11141ab3; }

/* Busca com atalho */
.dk-search { height: var(--control-height); width: 310px; padding: 0 8px 0 16px; border-radius: var(--radius-control);
  background: var(--glass-control); border: 1px solid var(--glass-edge); display: flex; align-items: center; gap: 12px;
  color: var(--on-accent-subtle); font: 400 15px/1 var(--font-text); }
.dk-search .dk-icon { color: var(--on-accent-muted); }
.dk-search .dk-ph { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dk-search.dk-focus { background: var(--glass-hover); border-color: var(--glass-edge-strong); color: var(--on-accent); }
.dk-key { height: 26px; padding: 0 8px; border-radius: 7px; background: var(--keycap-bg); border: 1px solid var(--glass-edge);
  display: inline-flex; align-items: center; font: 600 11px/1 var(--font-text); color: var(--on-accent-subtle); }

/* Painel da lista */
.dk-panel { width: var(--list-width); border-radius: var(--radius-card); padding: 16px 12px 12px; display: flex; flex-direction: column; gap: 6px; }
.dk-tabs { display: flex; gap: 4px; padding: 0 8px 6px; }
.dk-tab { height: 38px; padding: 0 18px; border-radius: var(--radius-full); display: inline-flex; align-items: center;
  color: var(--on-accent-muted); font: 500 15px/1 var(--font-text); }
.dk-tab.dk-current { background: linear-gradient(180deg, var(--glass-item-highlight) 0%, #ffffff0a 60%), var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge), inset 0 1px 0 #ffffff33; color: var(--on-accent); font-weight: 600; }
.dk-tab.dk-hover { background: var(--glass-hover); }
.dk-count { height: 36px; padding: 0 12px; display: flex; align-items: center; justify-content: space-between; color: var(--on-accent-subtle); font: 500 13px/1 var(--font-text); }
.dk-count .dk-icon { width: 16px; height: 16px; color: var(--on-accent-subtle); }
.dk-game { height: var(--game-row-height); padding: 0 6px 0 8px; border-radius: var(--radius-row); display: flex; align-items: center; gap: 14px;
  color: var(--on-accent); font: 500 15px/1.2 var(--font-text); border: 1px solid transparent; }
.dk-game .dk-title { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dk-game.dk-missing { color: var(--on-accent-muted); }
.dk-game { transition: background-color var(--tempo-hover) var(--curva-estado), box-shadow var(--tempo-hover) var(--curva-estado); }
.dk-game.dk-selected { font-weight: 600;
  background: linear-gradient(180deg, var(--glass-item-highlight) 0%, #ffffff0a 60%), var(--glass-selected);
  -webkit-backdrop-filter: blur(var(--glass-item-blur)) saturate(var(--glass-saturate)); backdrop-filter: blur(var(--glass-item-blur)) saturate(var(--glass-saturate));
  box-shadow: inset 0 0 0 1px var(--glass-item-edge), inset 0 1px 0 #ffffff33, 0 6px 16px #00000038; }
.dk-game.dk-hover { background: var(--glass-hover); }
.dk-thumb { width: 40px; height: 40px; border-radius: var(--radius-thumb); flex: none;
  background: linear-gradient(160deg, var(--t, var(--accent)) 0%, var(--td, var(--accent-deep)) 100%); }
.dk-rowplay { width: 36px; height: 36px; border-radius: 50%; flex: none; background: var(--glass-pressed); border: 1px solid var(--glass-edge-strong);
  display: flex; align-items: center; justify-content: center; }
.dk-rowplay .dk-icon { width: 18px; height: 18px; }
.dk-run { width: 8px; height: 8px; border-radius: 50%; background: var(--success); flex: none; margin-right: 8px; }

/* Destaque: etiqueta, título, tempo, metadados */
.dk-hero { display: flex; flex-direction: column; gap: 14px; align-items: flex-start; }
.dk-badge { height: 26px; padding: 0 12px; border-radius: var(--radius-full); border: 1px solid var(--glass-edge-strong); background: var(--glass-control);
  display: inline-flex; align-items: center; gap: 6px; font: 700 12px/1 var(--font-text); letter-spacing: .1em; text-transform: uppercase; color: var(--on-accent); }
.dk-display { font: 800 56px/1.02 var(--font-text); letter-spacing: -.025em; margin: 0; max-width: 620px; overflow-wrap: anywhere; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.dk-time { display: flex; align-items: center; gap: 10px; font: 400 17px/1 var(--font-text); color: var(--on-accent-muted); }
.dk-time b { color: var(--on-accent); font-weight: 700; }
.dk-meta { display: flex; align-items: stretch; gap: 18px; }
.dk-meta > div { display: flex; flex-direction: column; gap: 4px; }
.dk-meta span { font: 500 13px/1.3 var(--font-text); color: var(--on-accent-muted); }
.dk-meta b { font: 500 15px/1.25 var(--font-text); color: var(--on-accent); }
.dk-vsep { width: 1px; background: var(--divider); }
.dk-actions { display: flex; align-items: center; gap: 12px; margin-top: 6px; }

/* Cartões */
.dk-card { border-radius: var(--radius-card); padding: 20px; min-height: var(--card-height); display: flex; flex-direction: column; gap: 12px; }
.dk-h { font: 700 20px/1.25 var(--font-text); margin: 0; }
.dk-p { font: 400 15px/1.55 var(--font-text); color: var(--on-accent-muted); margin: 0; }
.dk-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: auto; }
.dk-chip { height: 32px; padding: 0 14px; border-radius: var(--radius-full); background: var(--glass-control); border: 1px solid var(--glass-edge);
  display: inline-flex; align-items: center; font: 500 13px/1 var(--font-text); color: var(--on-accent); }
.dk-chip.dk-hover { background: var(--glass-hover); }
.dk-glass.dk-trailer { padding: 0; overflow: hidden; justify-content: flex-end;
  background: var(--art-img) 70% 45% / 240% auto no-repeat; backdrop-filter: none; -webkit-backdrop-filter: none; }
.dk-trailer::before { z-index: 2; }
.dk-trailer::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(0deg, #0b0b0ecc 0%, #0b0b0e00 55%); }
.dk-trailer .dk-btn { position: relative; z-index: 1; margin: 0 0 16px 16px; align-self: flex-start; height: 40px; }
.dk-kv { display: grid; grid-template-columns: 20px minmax(96px, max-content) minmax(0, 1fr); align-items: center; column-gap: 12px;
  padding: 4px 0; border-top: 1px solid var(--divider); font: 500 13px/1.3 var(--font-text); }
.dk-kv:first-of-type { border-top: 0; }
.dk-kv .dk-icon { width: 16px; height: 16px; color: var(--on-accent-subtle); }
.dk-kv span { color: var(--on-accent-subtle); white-space: nowrap; }
.dk-kv b { font-weight: 500; color: var(--on-accent); min-width: 0; overflow-wrap: anywhere; }
.dk-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--success); margin-right: 8px; vertical-align: 1px; }

/* Linhas de configuração e camadas, no mesmo material */
.dk-row { min-height: 56px; padding: 10px 14px 10px 18px; border-radius: var(--radius-control); display: flex; align-items: center; gap: 14px;
  background: var(--glass-control); border: 1px solid var(--glass-edge); color: var(--on-accent); font: 500 15px/1.25 var(--font-text); }
.dk-row.dk-hover { background: var(--glass-hover); }
.dk-row.dk-disabled { opacity: .45; }
.dk-row.dk-danger { color: var(--error); }
.dk-row .dk-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.dk-row .dk-desc { font: 400 13px/1.35 var(--font-text); color: var(--on-accent-muted); }
.dk-row .dk-val { font: 500 13px/1 var(--font-text); color: var(--on-accent-muted); white-space: nowrap; }
.dk-row .dk-val.dk-em { color: var(--on-accent); font-weight: 600; }
.dk-row .dk-arrow { color: var(--on-accent-subtle); font: 400 18px/1 var(--font-text); }
.dk-row-header { padding: 14px 4px 6px; color: var(--on-accent-subtle); font: 700 12px/1 var(--font-text); letter-spacing: .1em; text-transform: uppercase; }
.dk-adj { width: 32px; height: 32px; border-radius: 50%; background: var(--glass-control); border: 1px solid var(--glass-edge);
  display: inline-flex; align-items: center; justify-content: center; font: 600 15px/1 var(--font-text); }
.dk-toggle { position: relative; width: 50px; height: 30px; border-radius: 15px; background: var(--glass-pressed); flex: none; }
.dk-toggle::after { content: ""; position: absolute; top: 3px; left: 3px; width: 24px; height: 24px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px #00000059; }
.dk-toggle.dk-on { background: var(--success); }
.dk-toggle.dk-on::after { left: 23px; }
.dk-mark { width: 20px; height: 20px; border: 2px solid var(--on-accent-muted); border-radius: 50%; flex: none; display: flex; align-items: center; justify-content: center; }
.dk-mark.dk-check { border-radius: 6px; }
.dk-mark.dk-on { border-color: var(--on-accent); background: var(--on-accent); }
.dk-mark.dk-on::after { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--on-primary); }
.dk-mark.dk-check.dk-on::after { border-radius: 2px; }
.dk-slider { width: 150px; height: 6px; border-radius: 3px; background: var(--glass-pressed); overflow: hidden; flex: none; }
.dk-slider i { display: block; height: 100%; background: var(--on-accent); border-radius: 3px; }

.dk-cats { width: 240px; display: flex; flex-direction: column; gap: 4px; flex: none; }
.dk-cats-title { font: 700 28px/1.15 var(--font-text); letter-spacing: -.01em; margin: 4px 8px 14px; }
.dk-cat { height: 44px; padding: 0 14px; border-radius: var(--radius-full); display: flex; align-items: center; gap: 12px; color: var(--on-accent-muted); font: 500 15px/1 var(--font-text); }
.dk-cat.dk-current { background: linear-gradient(180deg, var(--glass-item-highlight) 0%, #ffffff0a 60%), var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge), inset 0 1px 0 #ffffff33; color: var(--on-accent); font-weight: 600; }
.dk-cat.dk-hover { background: var(--glass-hover); }

.dk-scrim { position: relative; width: 100%; min-height: 100%; background: #0b0b0e99; display: flex; align-items: center; justify-content: center; padding: 24px; }
.dk-dialog { width: 480px; padding: 24px; border-radius: var(--radius-card); background: var(--glass-panel); border: 1px solid var(--glass-edge);
  box-shadow: var(--shadow-layer); display: flex; flex-direction: column; gap: 10px; }
.dk-dialog .dk-rows { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; }
.dk-panel-side { margin-left: auto; width: 440px; min-height: 440px; padding: 22px; border-radius: var(--radius-card); background: var(--glass-panel);
  border: 1px solid var(--glass-edge); box-shadow: var(--shadow-layer); display: flex; flex-direction: column; gap: 8px; }
.dk-menu { width: 260px; padding: 6px; border-radius: var(--radius-control); background: var(--glass-panel); border: 1px solid var(--glass-edge);
  box-shadow: var(--shadow-layer); display: flex; flex-direction: column; gap: 2px; }
.dk-menu-title { height: 30px; display: flex; align-items: center; padding: 0 10px; color: var(--on-accent-subtle); font: 600 13px/1 var(--font-text); }
.dk-menu-item { height: 36px; padding: 0 10px; border-radius: 10px; display: flex; align-items: center; gap: 10px; font: 500 15px/1 var(--font-text); }
.dk-menu-item .dk-icon { width: 18px; height: 18px; color: var(--on-accent-muted); }
.dk-menu-item.dk-hover { background: var(--glass-hover); }
.dk-menu-item.dk-danger, .dk-menu-item.dk-danger .dk-icon { color: var(--error); }
.dk-field { height: var(--control-height); border-radius: var(--radius-control); background: var(--glass-control); border: 1px solid var(--glass-edge-strong);
  display: flex; align-items: center; padding: 0 14px; font: 400 15px/1 var(--font-text); }
.dk-sel { background: var(--glass-pressed); }
.dk-toast { height: 44px; padding: 0 20px; border-radius: var(--radius-full); background: var(--glass-panel); border: 1px solid var(--glass-edge-strong);
  box-shadow: var(--shadow-layer); display: inline-flex; align-items: center; gap: 10px; font: 600 15px/1 var(--font-text); }
.dk-filter-badge { position: absolute; top: -6px; right: -6px; min-width: 20px; height: 20px; padding: 0 6px; border-radius: 10px; background: var(--on-accent);
  color: var(--on-primary); display: flex; align-items: center; justify-content: center; font: 700 11px/1 var(--font-text); }
.dk-rel { position: relative; display: inline-flex; }

.dk-dialog, .dk-panel-side, .dk-menu, .dk-toast {
  background: linear-gradient(180deg, var(--glass-highlight) 0%, #ffffff00 40%), var(--glass-panel-dense) !important;
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate)); backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  border: 1px solid var(--glass-edge-strong) !important; }

/* Reduzir transparência: sem lente, sem brilho; a arte continua atrás, mas nada a deixa passar. */
@media (prefers-reduced-transparency: reduce) {
  .dk-glass, .dk-btn, .dk-badge, .dk-dialog, .dk-panel-side, .dk-menu, .dk-toast {
    background: var(--glass-solid) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
}
[data-theme="solido"] .dk-glass, [data-theme="solido"] .dk-btn, [data-theme="solido"] .dk-badge {
  background: var(--glass-solid) !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
.dk-hero { text-shadow: 0 1px 18px #0b0b0e73; }

/* Configurações: fundo cinza, sem arte e sem vidro. Superfícies opacas settings-surface. */
.dk-stage.dk-gray { background: var(--settings-bg); }
.dk-gray .dk-glass { background: var(--settings-surface); backdrop-filter: none; -webkit-backdrop-filter: none;
  box-shadow: inset 0 0 0 1px #ffffff12, var(--shadow-float); }
.dk-gray .dk-glass::before, .dk-gray .dk-btn::before { display: none; }
.dk-gray .dk-btn { background: var(--settings-surface); backdrop-filter: none; -webkit-backdrop-filter: none; box-shadow: inset 0 0 0 1px #ffffff14; }
.dk-gray .dk-glass .dk-btn { background: var(--glass-control); }
.dk-gray .dk-row { background: var(--settings-surface); border-color: #ffffff0f; }
.dk-gray .dk-row.dk-hover { background: #3a3a3c; }
.dk-set-title { font: 700 28px/1.15 var(--font-text); letter-spacing: -.01em; margin: 4px 0 6px; }

/* Configurações: a mesma estrutura da biblioteca (barra superior, painel à esquerda, conteúdo à direita) sobre o cinza.
   Ícones das categorias sem fundo, na cor do texto. Do macOS 27 vêm as linhas agrupadas com divisórias. */
.st-tile { display: flex; align-items: center; justify-content: center; background: none !important; color: var(--on-accent-muted); }
.dk-selected .st-tile, .st-head .st-tile { color: var(--on-accent); }
.st-tile .dk-icon { width: 22px; height: 22px; }
.st-head { display: flex; align-items: center; gap: 18px; margin: 4px 0 22px; }
.st-head .dk-thumb { width: 48px; height: 48px; }
.st-head .dk-icon { width: 34px; height: 34px; }
.st-head b { display: block; font: 700 28px/1.15 var(--font-text); letter-spacing: -.01em; }
.st-head > div > span { display: block; margin-top: 6px; font: 400 15px/1.4 var(--font-text); color: var(--on-accent-muted); }
.st-h { font: 700 12px/1.2 var(--font-text); letter-spacing: .1em; text-transform: uppercase; color: var(--on-accent-subtle); margin: 18px 0 8px 4px; }
.st-group { background: var(--settings-surface); border-radius: var(--radius-card); overflow: hidden; box-shadow: inset 0 0 0 1px #ffffff12; }
.st-row { min-height: var(--settings-row-height); padding: 12px 14px 12px 18px; display: flex; align-items: center; gap: 16px; position: relative; }
.st-row + .st-row::before { content: ""; position: absolute; top: 0; left: 18px; right: 0; height: 1px; background: var(--settings-separator); }
.st-row.dk-hover { background: #ffffff0a; }
.st-lbl { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; font: 500 15px/1.3 var(--font-text); }
.st-lbl small { font: 400 13px/1.35 var(--font-text); color: var(--on-accent-muted); }
.st-pill { height: 36px; padding: 0 16px; border-radius: var(--radius-full); background: var(--settings-control); display: inline-flex; align-items: center; gap: 8px;
  font: 600 14px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; flex: none; box-shadow: inset 0 1px 0 #ffffff1a; }
.st-pill.dk-hover { background: var(--settings-control-hover); }
.st-pill svg { width: 10px; height: 14px; color: var(--on-accent-muted); }
.st-val { font: 500 14px/1 var(--font-text); color: var(--on-accent-muted); white-space: nowrap; }
.st-danger { color: var(--error); }
.st-note { font: 400 13px/1.4 var(--font-text); color: var(--on-accent-muted); margin: 8px 4px 0; }

/* Guias da barra superior, como na Steam: texto em caixa alta, sem botão. Configurações fica no menu da marca. */
.dk-guias { display: flex; align-items: stretch; gap: 28px; height: 100%; margin-left: 4px; }
.dk-guia { position: relative; display: inline-flex; align-items: center; font: 700 15px/1 var(--font-text); letter-spacing: .04em; text-transform: uppercase;
  color: var(--on-accent-muted); white-space: nowrap; transition: color var(--tempo-hover) var(--curva-estado); }
.dk-guia.dk-hover { color: var(--on-accent); }
.dk-guia.dk-current { color: var(--on-accent); }
.dk-guia.dk-current::after { content: ""; position: absolute; left: 0; right: 0; bottom: 12px; height: 2px; border-radius: 1px; background: var(--on-accent); }
/* Marca = botão do menu do Tako (como o menu "Steam") */
.dk-brand { height: 44px; padding: 0 10px 0 8px; margin-left: -8px; border-radius: var(--radius-full); transition: background-color var(--tempo-hover) var(--curva-estado); }
.dk-brand.dk-hover, .dk-brand.dk-open { background: var(--glass-hover); }
.dk-chev { width: 12px; height: 12px; color: var(--on-accent-muted); margin-left: -2px; }
.dk-menu-sep { height: 1px; background: var(--divider); margin: 4px 8px; }
.dk-menu-item .dk-kbd { margin-left: auto; font: 500 12px/1 var(--font-text); color: var(--on-accent-subtle); }
.dk-guias + .dk-btn { margin-left: 16px; }
/* Filtrar e ordenar: botão redondo na linha das abas, à direita de Coleções */
.dk-tabsrow { display: flex; align-items: center; gap: 4px; padding: 0 4px 6px 0; }
.dk-tabsrow .dk-tabs { padding: 0 0 0 4px; gap: 2px; flex: none; }
.dk-tabsrow .dk-tab { padding: 0 13px; }
.dk-tabfilter { margin-left: auto; flex: none; }
.dk-tabfilter .dk-btn.dk-round { width: 38px; height: 38px; }
.dk-tabfilter .dk-btn.dk-round .dk-icon { width: 18px; height: 18px; }
.dk-tabfilter .dk-filter-badge { top: -4px; right: -4px; min-width: 18px; height: 18px; font-size: 10px; }
/* Tela cheia na barra: mesmo raio da busca ao lado */
.dk-top .dk-btn, .dk-btn.dk-sq { border-radius: var(--radius-control); }

/* Padrão da TelaBiblioteca para linhas: dentro de um vidro, linhas seguidas formam UM grupo com divisórias
   (como a lista de jogos e os grupos das Configurações), nunca caixas soltas. */
.dk-group { background: var(--glass-control); border-radius: var(--radius-control); box-shadow: inset 0 0 0 1px var(--glass-edge); overflow: hidden; flex: none; }
.dk-group > .dk-row { background: none; border: 0; border-radius: 0; position: relative; }
.dk-group > .dk-row + .dk-row::before { content: ""; position: absolute; top: 0; left: 18px; right: 0; height: 1px; background: var(--divider); }
.dk-group > .dk-row.dk-hover { background: var(--glass-hover); }
/* Opção solta num diálogo (Não perguntar de novo): linha sem caixa */
.dk-dialog .dk-rows > .dk-row { background: none; border: 0; padding-left: 4px; min-height: 44px; }

/* Foco (teclado/controle), estilo Apple TV: clareia + contorno fino + brilho suave. Sem linha branca grossa. */
.dk-ring.dk-ring { outline: none !important;
  background-image: linear-gradient(var(--focus-fill), var(--focus-fill)) !important;
  box-shadow: inset 0 0 0 1px var(--focus-ring), 0 0 0 var(--focus-ring-width) var(--focus-glow), 0 6px 18px #00000040 !important; }
.st-row.dk-ring.dk-ring { box-shadow: inset 0 0 0 1px var(--focus-ring) !important; border-radius: var(--radius-card); }
.dk-guia.dk-ring.dk-ring { background-image: none !important; box-shadow: none !important; text-shadow: 0 0 12px #ffffff80; color: var(--on-accent); }

/* UI UX Pro Max: todo elemento clicável mostra a mão; texto cortado tem o nome completo na dica (title/aria-label). */
.dk-btn, .dk-play, .dk-tab, .dk-guia, .dk-brand, .dk-game, .dk-chip, .dk-row, .st-row, .st-pill, .dk-menu-item, .dk-adj, .dk-rowplay, .dk-search, .dk-cat { cursor: pointer; }
.dk-disabled, .dk-row.dk-disabled { cursor: not-allowed; }
/* Estado vazio da lista */
.dk-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 10px; padding: 28px 20px 36px; }
.dk-empty .dk-icon { width: 32px; height: 32px; color: var(--on-accent-subtle); margin-bottom: 4px; }
.dk-empty b { font: 700 17px/1.3 var(--font-text); }
.dk-empty span { font: 400 14px/1.45 var(--font-text); color: var(--on-accent-muted); max-width: 260px; }
.dk-empty .dk-btn { margin-top: 6px; }

/* Abas como seletor segmentado (estilo Apple): um trilho de vidro, opções de largura igual,
   a escolhida com a segunda camada de vidro da lista. Sem botões soltos. */
.dk-tabs.dk-seg2 { display: flex; gap: 2px; padding: 3px; margin: 0 0 4px; border-radius: var(--radius-control);
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.dk-seg2 .dk-tab { flex: 1; justify-content: center; height: 34px; padding: 0 6px; border-radius: 11px; font: 500 14px/1 var(--font-text); }
.dk-seg2 .dk-tab.dk-current { font-weight: 600; }
.dk-seg2 .dk-tab.dk-hover { background: var(--glass-hover); }
/* Ações da contagem (ordenar, filtrar): ícones discretos, sem botão, como a linha de status do painel */
.dk-count { padding-right: 4px; }
.dk-countact { display: inline-flex; gap: 2px; }
.dk-iconbtn { width: 30px; height: 30px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center;
  color: var(--on-accent-muted); transition: background-color var(--tempo-hover) var(--curva-estado), color var(--tempo-hover) var(--curva-estado); cursor: pointer; }
.dk-iconbtn .dk-icon { width: 17px; height: 17px; color: inherit; }
.dk-iconbtn.dk-hover { background: var(--glass-hover); color: var(--on-accent); }
.dk-iconbtn.dk-on { color: var(--on-accent); }
.dk-iconbtn:has(.dk-mini) { width: auto; padding: 0 8px 0 7px; gap: 5px; }
.dk-mini { font: 700 12px/1 var(--font-text); color: var(--on-accent); }

/* ===== Áreas novas: Loja, Perfil, Configurações deste jogo, Assistente ===== */
/* Loja: preço e desconto na linha da lista */
.dk-pricecol { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; flex: none; }
.dk-pricecol s { font: 500 11px/1 var(--font-text); color: var(--on-accent-subtle); }
.dk-pricecol b { font: 600 14px/1 var(--font-text); color: var(--on-accent); }
.dk-off { min-width: 46px; height: 24px; padding: 0 7px; border-radius: 7px; display: inline-flex; align-items: center; justify-content: center; flex: none;
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); font: 700 12px/1 var(--font-text); color: var(--on-accent); }
.dk-game .dk-title .dk-owned-tag { display: block; margin-top: 3px; font: 500 11px/1 var(--font-text); color: var(--on-accent-subtle); }
.dk-game.dk-owned .dk-title { line-height: 1.1; }
.dk-strike { text-decoration: line-through; color: var(--on-accent-subtle); }
.dk-affiliate { display: flex; align-items: center; gap: 8px; max-width: 560px; font: 400 13px/1.4 var(--font-text); color: var(--on-accent-muted); }
.dk-affiliate .dk-icon { width: 16px; height: 16px; flex: none; }
.dk-chart { flex: 1; display: flex; align-items: flex-end; gap: 6px; min-height: 0; padding-top: 4px; }
.dk-chart i { flex: 1; border-radius: 4px 4px 2px 2px; background: var(--glass-selected); }
.dk-chart i.dk-low { background: var(--primary-top); }
.dk-chart-x { display: flex; justify-content: space-between; font: 500 11px/1 var(--font-text); color: var(--on-accent-subtle); }
.dk-shop { display: grid; grid-template-columns: 1fr auto 48px; align-items: center; gap: 12px; padding: 9px 0; border-top: 1px solid var(--divider); font: 500 14px/1.2 var(--font-text); }
.dk-shop:first-of-type { border-top: 0; }
.dk-shop span { color: var(--on-accent-muted); }
.dk-shop em { font: 700 12px/1 var(--font-text); font-style: normal; color: var(--on-accent-subtle); text-align: right; }
.dk-shop.dk-best span, .dk-shop.dk-best em { color: var(--on-accent); }
/* Perfil */
.dk-me { display: flex; align-items: center; gap: 12px; padding: 4px 4px 14px; margin-bottom: 6px; border-bottom: 1px solid var(--divider); }
.dk-me > div { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.dk-me b { font: 700 17px/1.2 var(--font-text); }
.dk-me span:not(.dk-avatar):not(.dk-iconbtn) { font: 400 13px/1.2 var(--font-text); color: var(--on-accent-muted); }
.dk-avatar { width: 48px; height: 48px; border-radius: 50%; flex: none; display: flex; align-items: center; justify-content: center;
  background: linear-gradient(160deg, color-mix(in srgb, var(--accent-exemplo) 80%, #fff 0%), color-mix(in srgb, var(--accent-exemplo) 45%, #000)); font: 700 20px/1 var(--font-text); box-shadow: inset 0 0 0 1px #ffffff2e; }
.dk-stat { padding: 16px 18px; display: flex; flex-direction: column; gap: 14px; }
.dk-stat-h { display: flex; flex-direction: column; gap: 6px; }
.dk-stat-h span { font: 500 13px/1 var(--font-text); color: var(--on-accent-muted); }
.dk-stat-h b { font: 700 22px/1.15 var(--font-text); letter-spacing: -.01em; }
.dk-week { height: 120px; display: flex; gap: 10px; align-items: stretch; }
.dk-wbar { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; gap: 6px; }
.dk-wbar i { width: 100%; max-width: 34px; border-radius: 6px 6px 3px 3px; background: var(--primary-top); }
.dk-wbar span { font: 500 11px/1 var(--font-text); color: var(--on-accent-subtle); }
.st-row .dk-thumb { flex: none; }
/* Configurações deste jogo */
.dk-sub { display: block; margin-top: 4px; font: 500 13px/1 var(--font-text); color: var(--on-accent-muted); }
/* Assistente: indicador de passos */
.dk-steps { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
.dk-steps i { flex: 1; height: 1px; background: var(--divider); }
.dk-step { height: 30px; padding: 0 12px; border-radius: 9px; display: inline-flex; align-items: center; gap: 6px; font: 500 13px/1 var(--font-text); color: var(--on-accent-subtle); white-space: nowrap; }
.dk-step .dk-icon { width: 15px; height: 15px; }
.dk-step.dk-done { color: var(--on-accent-muted); }
.dk-step.dk-now { color: var(--on-accent); font-weight: 600;
  background: linear-gradient(180deg, var(--glass-item-highlight) 0%, #ffffff0a 60%), var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge), inset 0 1px 0 #ffffff33; }
.dk-overline { font: 700 12px/1 var(--font-text); letter-spacing: .1em; text-transform: uppercase; color: var(--on-accent-subtle); }
.dk-chart i.dk-now { background: var(--glass-control); box-shadow: inset 0 0 0 1.5px var(--on-accent); }

/* Loja › vitrine */
.dk-feature { position: relative; display: flex; gap: 22px; padding: 16px; border-radius: var(--radius-card); height: 352px; flex: none; }
.dk-feature-art { width: 570px; flex: none; border-radius: 14px; background: var(--art-img) 55% 30% / cover no-repeat; box-shadow: inset 0 0 0 1px #ffffff1f; }
.dk-feature-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 12px; padding: 6px 30px 0 0; }
.dk-feature-title { margin: -4px 0 0; font: 800 34px/1.05 var(--font-text); letter-spacing: -.02em; }
.dk-shots { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.dk-shot { aspect-ratio: 16/9; border-radius: 8px; background-image: var(--art-img); background-size: 360%; box-shadow: inset 0 0 0 1px #ffffff1a; }
.dk-feature .dk-chips { margin-top: 0; }
.dk-owned-line { display: inline-flex; align-items: center; gap: 6px; font: 600 13px/1 var(--font-text); color: var(--on-accent); }
.dk-owned-line .dk-icon { width: 15px; height: 15px; color: var(--success); }
.dk-buyline { display: flex; align-items: center; gap: 10px; margin-top: auto; }
.dk-off-lg { height: 34px; min-width: 64px; font-size: 16px; border-radius: 9px; }
.dk-car { position: absolute; top: 50%; transform: translateY(-50%); width: 40px !important; height: 40px !important; font: 400 22px/1 var(--font-text); }
.dk-car-l { left: -14px; } .dk-car-r { right: -14px; }
.dk-dots { display: flex; justify-content: center; gap: 6px; margin-top: -4px; }
.dk-dots i { width: 8px; height: 8px; border-radius: 4px; background: #ffffff40; transition: width var(--tempo-pagina) var(--curva-entrada); }
.dk-dots i.dk-on { width: 22px; background: var(--on-accent); }
.dk-section-h { display: flex; align-items: baseline; justify-content: space-between; padding: 2px 4px 0; }
.dk-section-h span:first-child { font: 700 12px/1 var(--font-text); letter-spacing: .1em; text-transform: uppercase; color: var(--on-accent-muted); }
.dk-link { font: 600 13px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; }
.dk-capsules { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; flex: 1; min-height: 0; }
.dk-capsule { border-radius: var(--radius-card); padding: 10px; display: flex; flex-direction: column; gap: 10px; cursor: pointer; }
.dk-cover { aspect-ratio: 16/9; border-radius: 12px; display: flex; align-items: flex-end; padding: 10px 12px;
  background: radial-gradient(120% 90% at 80% 10%, var(--c1), var(--c2)); box-shadow: inset 0 0 0 1px #ffffff1a; }
.dk-cover span { font: 800 18px/1.05 var(--font-text); letter-spacing: -.01em; text-shadow: 0 2px 12px #00000080; }
.dk-capsule-info { display: flex; flex-direction: column; gap: 6px; padding: 0 4px 2px; }
.dk-capsule-info > b { font: 600 15px/1.2 var(--font-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dk-capsule-store { font: 500 12px/1 var(--font-text); color: var(--on-accent-subtle); }
.dk-capsule .dk-buyline { margin-top: 4px; justify-content: space-between; }
.dk-loja .dk-panel { display: flex; flex-direction: column; }
.dk-dots i { display: block; }
.dk-capsules { flex: none; align-items: start; }
.dk-cover { align-items: center; justify-content: center; }
.dk-cover .dk-icon { width: 28px; height: 28px; color: #ffffff40; }
.dk-pricechips { display: flex; flex-wrap: wrap; gap: 10px; }
.dk-pchip { height: 44px; padding: 0 18px; border-radius: var(--radius-control); display: inline-flex; align-items: center; gap: 8px; cursor: pointer;
  background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px), var(--glass-panel);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate)); backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  box-shadow: inset 0 0 0 1px var(--glass-edge), var(--shadow-float); font: 600 14px/1 var(--font-text); }
.dk-pchip .dk-icon { width: 17px; height: 17px; }
.dk-dots { align-self: center; padding: 6px 10px; border-radius: var(--radius-full); background: var(--glass-panel);
  -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.dk-dots i { background: #ffffff59; }
.dk-dots i.dk-on { background: var(--on-accent); }
/* Títulos de seção ficam direto sobre a arte: texto claro + sombra difusa (vibrância), como o Destaque */
.dk-section-h span:first-child, .dk-section-h .dk-link { color: var(--on-accent); text-shadow: 0 1px 14px #0b0b0ee6, 0 0 2px #0b0b0eb3; }
.dk-section-h { align-items: center; }
.dk-section-h .dk-link { height: 28px; padding: 0 12px; border-radius: var(--radius-full); display: inline-flex; align-items: center; text-shadow: none;
  background: var(--glass-panel); -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); box-shadow: inset 0 0 0 1px var(--glass-edge); }

/* Reduzir animações: sem movimento; cor (hover) continua */
@media (prefers-reduced-motion: reduce) {
  .dk-btn.dk-pressed, .dk-play.dk-pressed { transform: none; }
  .dk-dots i { transition: none; }
}

/* ===== Estados da tela principal ===== */
.dk-badge-run { gap: 7px; }
.dk-badge-run i { width: 7px; height: 7px; border-radius: 50%; background: var(--success); box-shadow: 0 0 8px var(--success); }
.dk-time-sep { margin: 0 2px; color: var(--on-accent-subtle); }
.dk-pill-lg { height: 56px !important; padding: 0 24px !important; font-size: 16px !important; }
/* Sem arte: degradê da cor do jogo */
.dk-semarte .dk-art { background: radial-gradient(70% 90% at 78% 18%, color-mix(in srgb, var(--accent) 85%, #fff 0%), transparent 70%),
  linear-gradient(160deg, var(--accent), var(--accent-deep) 75%) !important; }
.dk-semarte .dk-art::before { display: none; }
/* Carregando: blocos de espera nos tamanhos do conteúdo */
.dk-carregando .dk-art { background: radial-gradient(60% 80% at 75% 20%, color-mix(in srgb, var(--accent) 60%, transparent), transparent 70%), var(--canvas) !important; }
.dk-carregando .dk-art::before { display: none; }
.dk-sk { display: block; flex: none; background: var(--glass-control); box-shadow: inset 0 0 0 1px #ffffff0a; animation: dk-pulse var(--tempo-pulso) ease-in-out infinite; }
.dk-game .dk-sk + .dk-sk { margin-left: 0; }
@keyframes dk-pulse { 50% { opacity: .55; } }
@media (prefers-reduced-motion: reduce) { .dk-sk { animation: none; } }
/* Janela pequena 960×600 */
.dk-small [style*="padding:12px 36px 28px"] { padding: 10px 20px 16px !important; gap: 14px !important; }
.dk-small [style*="gap:28px;flex:1"] { gap: 20px !important; }
.dk-small .dk-panel { width: 300px !important; overflow: hidden; }
.dk-small .dk-top { padding: 0 8px 0 14px; gap: 8px; }
.dk-small .dk-brand { margin-right: 6px; }
.dk-small .dk-guias { gap: 18px; }
.dk-small .dk-search { width: 190px; }
.dk-small .dk-search .dk-key { display: none; }
