/* Loja › vitrine (destaque largo + fileiras) */
.dk-loja2 .dk-art { background: var(--art-img) right -40px top -40px / auto 115% no-repeat, var(--canvas); }
.dk-loja2 .dk-art::before { content: ""; position: absolute; inset: -60px; background: var(--art-img) right -40px top -40px / auto 115% no-repeat; filter: blur(42px) saturate(1.35);
  -webkit-mask-image: linear-gradient(90deg, #000 0%, #000 25%, transparent 50%); mask-image: linear-gradient(90deg, #000 0%, #000 25%, transparent 50%); }
.dk-loja2 .dk-art::after { background: linear-gradient(90deg, #0b0b0ed9 0%, #0b0b0eb3 38%, #0b0b0e00 62%), linear-gradient(0deg, #0b0b0ef2 0%, #0b0b0ecc 48%, #0b0b0e00 70%); }
.lj-hero { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; max-width: 640px; text-shadow: 0 1px 18px #0b0b0e73; }
