.lj-tiles { display: grid; grid-template-columns: repeat(7, 1fr); gap: 12px; }
.lj-tile { height: 58px; border-radius: var(--radius-control); padding: 0 14px; display: flex; align-items: center; gap: 10px; cursor: pointer; font: 600 14px/1.15 var(--font-text); }
