.lj-aff { font-size: 12px; margin-top: 2px; }
.dk-loja2 .dk-art, .dk-loja2 .dk-art::before { background-position: left 300px top -10px !important; background-size: auto 104% !important; }
.dk-loja2 .dk-art::before { -webkit-mask-image: linear-gradient(90deg, #000 0%, #000 18%, transparent 34%); mask-image: linear-gradient(90deg, #000 0%, #000 18%, transparent 34%); }
.dk-cover .lj-off { font: 700 12px/1 var(--font-text); text-shadow: none; }
.lj-tile em { min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px; display: inline-flex; align-items: center; justify-content: center;
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); color: var(--on-accent); }
.lj-tile span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Loja › oferta */
.lj-back { font: 600 14px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; margin-bottom: 4px; }
.lj-cards { display: flex; gap: 20px; height: 248px; }
.lj-hero .dk-affiliate { max-width: 600px; }

/* Loja refinada (UI UX Pro Max): controles do carrossel e das fileiras, ícone de link externo */
.dk-play .dk-ext { width: 18px; height: 18px; margin-left: 2px; opacity: .75; }
.lj-carousel { display: flex; align-items: center; gap: 6px; align-self: flex-start; margin: 2px 0 4px; padding: 4px; border-radius: var(--radius-full);
  background: var(--glass-panel); -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.lj-carousel .dk-dots { padding: 0 4px; background: none; box-shadow: none; backdrop-filter: none; -webkit-backdrop-filter: none; margin: 0; }
.lj-cbtn { width: 28px; height: 28px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; cursor: pointer;
  font: 400 18px/1 var(--font-text); color: var(--on-accent); transition: background-color var(--tempo-hover) var(--curva-estado); }
