.lj-hero .dk-affiliate { margin-top: 2px; }
/* Página do jogo na loja: linha de preço em degraus, voltar, link externo nas lojas */
.lj-back { height: 30px; padding: 0 12px; border-radius: var(--radius-full); display: inline-flex; align-items: center; text-shadow: none; color: var(--on-accent);
  background: var(--glass-panel); -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.lj-sum { font-size: 13px !important; margin-top: -6px !important; }
.lj-sum b { color: var(--on-accent); font-weight: 600; }
.lj-line { position: relative; flex: 1; min-height: 0; }
.lj-line svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.lj-area { fill: #ffffff14; }
.lj-path { fill: none; stroke: var(--on-accent-muted); stroke-width: 2; }
.lj-mark { position: absolute; width: 12px; height: 12px; margin: -6px 0 0 -6px; border-radius: 50%; }
.lj-mark-low { background: var(--primary-top); box-shadow: 0 0 0 3px #12141acc; }
.lj-mark-now { background: #12141a; box-shadow: inset 0 0 0 2px var(--on-accent), 0 0 0 3px #12141acc; margin-left: -12px; }
