.lj-shop { grid-template-columns: 1fr auto 44px 18px; cursor: pointer; }
.lj-shop .dk-ext { width: 15px; height: 15px; color: var(--on-accent-subtle); }

/* ===== Padrão de popup ===== */
.pp-scrim { position: absolute; inset: 0; z-index: 6; background: #0b0b0e8c; display: flex; align-items: center; justify-content: center; }
.pp { position: relative; display: flex; flex-direction: column; gap: 14px; padding: 24px; border-radius: var(--radius-card);
  background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px), var(--glass-panel-dense);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate)); backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  box-shadow: inset 0 0 0 1px var(--glass-edge-strong), var(--shadow-layer); color: var(--on-accent); }
.pp-s { width: 440px; } .pp-m { width: 540px; } .pp-l { width: 680px; }
.pp-head { display: flex; align-items: flex-start; gap: 14px; }
.pp-thumb { position: relative; width: 44px; height: 44px; border-radius: var(--radius-thumb); flex: none; background: linear-gradient(135deg, var(--t), var(--td)); box-shadow: inset 0 0 0 1px #ffffff1f; }
.pp-alert { position: absolute; right: -4px; bottom: -4px; width: 14px; height: 14px; border-radius: 50%; background: var(--warning); box-shadow: 0 0 0 3px #1a1c22; }
