.pp-sub { font: 500 13px/1.3 var(--font-text); color: var(--on-accent-muted); }
.pp-x { width: 32px; height: 32px; margin: -4px -6px 0 0; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; flex: none; cursor: pointer;
  color: var(--on-accent-muted); transition: background-color var(--tempo-hover) var(--curva-estado); }
.pp-x .dk-icon { width: 18px; height: 18px; }
.pp-text { margin: 0; font: 400 15px/1.55 var(--font-text); color: var(--on-accent-muted); }
.pp-small { font-size: 13px; }
.pp-disclose { display: flex; align-items: center; gap: 10px; height: 40px; padding: 0 14px; border-radius: var(--radius-control); cursor: pointer;
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); font: 500 14px/1 var(--font-text); }
.pp-disclose span:first-child { flex: 1; }
.pp-disclose code { font: 600 13px/1 ui-monospace, "Cascadia Mono", Consolas, monospace; color: var(--on-accent-muted); }
.pp-chev { color: var(--on-accent-subtle); font-size: 18px; }
.pp-foot { display: flex; align-items: center; gap: 10px; margin-top: 4px; }
.pp-sp { flex: 1; }
.pp-link { font: 600 14px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; text-decoration: underline; text-decoration-color: #ffffff40; text-underline-offset: 4px; }
.pp .dk-btn { height: 44px; }
.pp-primary { min-width: 0 !important; height: 44px !important; padding: 0 22px !important; font-size: 15px !important; }
.pp-fine { margin: -2px 0 0; font: 400 12px/1.4 var(--font-text); color: var(--on-accent-subtle); }
/* mídia no topo (loja) */
.pp-media { padding: 0; gap: 0; overflow: hidden; }
.pp-art { position: relative; height: 270px; background: var(--art-img) 60% 22% / cover no-repeat; box-shadow: inset 0 -60px 50px -30px #12141a; }
.pp-art .pp-x { position: absolute; top: 14px; right: 14px; margin: 0; background: var(--glass-panel); -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); color: var(--on-accent); }
.pp-pad { display: flex; flex-direction: column; gap: 12px; padding: 18px 24px 22px; }
/* cupom */
.pp-code { display: flex; align-items: center; gap: 10px; height: 64px; padding: 0 10px 0 20px; border-radius: var(--radius-control);
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); }
.pp-code code { flex: 1; font: 700 26px/1 ui-monospace, "Cascadia Mono", Consolas, monospace; letter-spacing: .12em; user-select: all; }
.pp-code .dk-btn .dk-icon { width: 17px; height: 17px; }
.pp-terms { margin: 0; padding: 0 0 0 18px; display: flex; flex-direction: column; gap: 6px; font: 400 14px/1.4 var(--font-text); color: var(--on-accent-muted); }
/* folha do padrão */
.pp-board { position: relative; z-index: 1; display: flex; gap: 70px; align-items: flex-start; padding: 40px 60px; }
.pp-col { display: flex; flex-direction: column; gap: 14px; align-items: flex-start; }
.pp-num { position: absolute; width: 22px; height: 22px; border-radius: 50%; display: flex; align-items: center; justify-content: center; background: var(--on-accent); color: var(--on-primary); font: 700 12px/1 var(--font-text); }
.pp-legend { font: 400 13px/1.7 var(--font-text); color: var(--on-accent-muted); }
.pp-legend b { display: inline-flex; width: 18px; height: 18px; border-radius: 50%; align-items: center; justify-content: center; background: var(--on-accent); color: var(--on-primary); font-size: 11px; margin-right: 6px; }
.pp-cap { font: 500 12px/1.4 var(--font-text); color: var(--on-accent-subtle); margin-bottom: 14px; }
.dk-stage > .pp-scrim.pp-scrim { position: absolute; inset: 0; z-index: 6; }

/* Gêneros no Sobre: metadado em texto, não botão (UI UX Pro Max: chip só quando é ação) */
.dk-tags { margin: auto 0 0; padding-top: 12px; border-top: 1px solid var(--glass-edge); display: flex; flex-wrap: wrap; align-items: center;
  font: 500 13px/20px var(--font-text); color: var(--on-accent-muted); }
.dk-tags span + span::before { content: "-"; margin: 0 8px; color: var(--on-accent-muted); }
.dk-feature .dk-tags { margin-top: 0; }
.dk-small .dk-tags { flex-wrap: nowrap; overflow: hidden; white-space: nowrap; }
.dk-small .dk-tags span:nth-child(n+3) { display: none; }

/* TelaPerfil (estrutura do perfil do PS5, material do Tako) */
.dk-stage > .pf-scrim.pf-scrim { position: absolute; inset: 0; z-index: 0; pointer-events: none;
  background: linear-gradient(180deg, #0b0b0e33 0%, #0b0b0e4d 26%, #0b0b0ecc 46%, var(--art-scrim-strong) 70%), linear-gradient(90deg, #0b0b0ea6 0%, #0b0b0e00 55%); }
.pf-page { flex: 1; min-height: 0; padding: 30px 36px 0; display: flex; flex-direction: column; }
.pf-head { display: flex; align-items: center; gap: 30px; }
.pf-avwrap { position: relative; flex: none; padding: 4px; border-radius: 50%;
  background: linear-gradient(160deg, #ffffff59, #ffffff0d 55%, #ffffff26); box-shadow: var(--shadow-float); }
.pf-me { box-shadow: inset 0 0 0 1px #ffffff2e, inset 0 -18px 30px #0000002e; text-shadow: 0 2px 10px #0000004d; }
