.pf-who { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
.pf-who h1 { margin: 0; font: 800 54px/1 var(--font-text); letter-spacing: -.025em; text-shadow: 0 1px 18px #0b0b0e73; }
.pf-line { display: flex; align-items: center; gap: 14px; font: 500 17px/1 var(--font-text); color: var(--on-accent-muted); }
.pf-line i { width: 1px; height: 16px; background: var(--glass-item-edge); }
.pf-play { display: inline-flex; align-items: center; gap: 8px; color: var(--on-accent); }
.pf-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--success); box-shadow: 0 0 0 3px color-mix(in srgb, var(--success) 25%, transparent); }
.pf-since { align-self: flex-end; margin-bottom: 4px; display: inline-flex; align-items: center; gap: 8px; font: 500 14px/1 var(--font-text); color: var(--on-accent-muted); }
.pf-since .dk-icon { width: 16px; height: 16px; }
.pf-nav { display: flex; align-items: flex-end; justify-content: space-between; margin: 34px 0 22px; }
.pf-tabs { display: flex; gap: 36px; }
.pf-tab { position: relative; font: 500 21px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; padding: 10px 0 14px; transition: color var(--tempo-hover) var(--curva-estado); }
.pf-tab.pf-cur { color: var(--on-accent); font-weight: 650; }
.pf-tab.pf-cur::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 2px; background: var(--on-accent); }
.pf-acts { display: flex; gap: 14px; padding-bottom: 4px; }
.pf-act { position: relative; width: 48px; height: 48px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer;
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); transition: background-color var(--tempo-hover) var(--curva-estado); }
.pf-act .dk-icon { width: 21px; height: 21px; }
.pf-act em { position: absolute; bottom: 58px; left: 50%; transform: translateX(-50%); white-space: nowrap; font: 600 13px/1 var(--font-text); font-style: normal;
  padding: 7px 10px; border-radius: 8px; background: var(--glass-panel-dense); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); opacity: 0; pointer-events: none; }
.pf-act.dk-hover { background: var(--focus-fill); box-shadow: inset 0 0 0 1px var(--focus-ring), 0 0 18px var(--focus-glow); }
.pf-act.dk-hover em { opacity: 1; }
.pf-tiles { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; }
.pf-tile { height: 310px; box-sizing: border-box; padding: 22px 24px 24px; border-radius: var(--radius-card); display: flex; flex-direction: column; gap: 16px;
  background: var(--glass-panel-dense); cursor: pointer; transition: transform var(--tempo-foco) var(--curva-entrada), box-shadow var(--tempo-foco) var(--curva-entrada); }
.pf-tile.pf-focus { transform: scale(1.025); box-shadow: inset 0 0 0 1px var(--focus-ring), 0 0 0 1px var(--focus-ring), 0 0 28px var(--focus-glow), var(--shadow-float); background: linear-gradient(180deg, var(--focus-fill), transparent 60%), var(--glass-panel-dense); }
.pf-vis { flex: 1; min-height: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; }
.pf-foot { display: flex; flex-direction: column; gap: 6px; padding-top: 14px; border-top: 1px solid var(--divider); }
.pf-foot span { font: 500 15px/1.2 var(--font-text); color: var(--on-accent-muted); }
.pf-foot b { font: 700 28px/1.1 var(--font-text); letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pf-chart { align-items: stretch; justify-content: flex-start; gap: 14px; }
.pf-chead { display: flex; justify-content: space-between; align-items: baseline; font: 500 13px/1 var(--font-text); color: var(--on-accent-muted); }
.pf-chead b { color: var(--on-accent); font-weight: 650; }
.pf-week { flex: 1; min-height: 0; display: flex; gap: 8px; align-items: stretch; }
.pf-b { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; gap: 7px; }
.pf-b i { width: 100%; max-width: 30px; max-height: calc(100% - 38px); border-radius: 4px 4px 2px 2px; background: var(--glass-item-highlight); flex: none; }
.pf-b span { font: 600 12px/1 var(--font-text); color: var(--on-accent-muted); }
.pf-b em { font: 700 12px/1 var(--font-text); font-style: normal; white-space: nowrap; }
