/* Sobre o jogo + Detalhes: grade de 8 pt, respiro de 24 nas bordas, título → conteúdo 16, linhas que preenchem o cartão por igual */
.dk-card:has(> .dk-p), .dk-card:has(> .dk-kv) { padding: 24px 24px 20px; }
.dk-card:has(> .dk-p) > .dk-h, .dk-card:has(> .dk-kv) > .dk-h { margin-bottom: 4px; }
.dk-card > .dk-p { max-width: 62ch; }
.dk-card > .dk-tags { padding-top: 16px; }
.dk-card:has(> .dk-kv) > .dk-h { margin-bottom: 8px; }
.dk-card > .dk-kv { flex: 1 1 0; min-height: 28px; max-height: 40px; padding: 0; column-gap: 16px;
  grid-template-columns: 16px minmax(104px, max-content) minmax(0, 1fr); font-size: 13px; }
.dk-card > .dk-kv b { font-weight: 600; }
.dk-small .dk-card:has(> .dk-p), .dk-small .dk-card:has(> .dk-kv) { padding: 16px; }
.dk-small .dk-card > .dk-kv { column-gap: 12px; grid-template-columns: 16px minmax(80px, max-content) minmax(0, 1fr); }
/* Mesmo respiro nos outros cartões da linha (Histórico de preço, Onde comprar) para os títulos alinharem */
.dk-card:has(> .lj-shop), .dk-card:has(> .lj-sum) { padding: 24px 24px 20px; }
.dk-card:has(> .lj-shop) > .dk-h { margin-bottom: 8px !important; }
/* Janela pequena: as linhas encolhem por igual e Série sai (fica no menu ⋯) para Status caber */
.dk-small .dk-card > .dk-kv { min-height: 0; }
.dk-small .dk-card > .dk-kv:nth-of-type(5) { display: none; }
/* Limites de texto de Sobre o jogo e Detalhes: nada passa da conta, o resto vai para "Mais" ou para a dica */
.dk-card > .dk-p { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 4; overflow: hidden; }
.dk-card > .dk-tags { flex-wrap: nowrap; white-space: nowrap; overflow: hidden; }
.dk-card > .dk-tags span { max-width: 18ch; overflow: hidden; text-overflow: ellipsis; flex: none; }
.dk-card > .dk-tags span + span::before { display: inline-block; }
.dk-tags .dk-tagmore { color: var(--on-accent-subtle); }
.dk-tags .dk-morelink { margin-left: auto; padding-left: 16px; color: var(--on-accent); font-weight: 600; min-height: 24px; display: inline-flex; align-items: center; }
.dk-tags .dk-morelink::before { content: none !important; }
.dk-card > .dk-kv b { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 24ch; overflow-wrap: normal; }
.dk-card > .dk-kv:nth-of-type(n+7) { display: none; }
.dk-mid .dk-card > .dk-p { -webkit-line-clamp: 3; }
.dk-small .dk-card > .dk-p { -webkit-line-clamp: 2; }
.dk-small .dk-card > .dk-tags span:nth-child(n+3):not(.dk-morelink):not(.dk-tagmore) { display: none; }
/* ===== Movimento: storyboards (quadros estáticos + linha do tempo + quadro ao vivo) ===== */
.dk-stage.mv-stage { background: var(--settings-bg); padding: 40px 44px; }
.mv-wrap { display: flex; flex-direction: column; gap: 24px; width: 100%; }
.mv-head { display: flex; flex-direction: column; gap: 8px; }
.mv-head .dk-h { font-size: 26px; }
.mv-head .dk-p { max-width: 96ch; }
.mv-seq { display: flex; flex-direction: column; gap: 20px; padding: 24px; border-radius: var(--radius-card); background: #ffffff08; border: 1px solid var(--glass-edge); }
.mv-seqh { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; font: 600 18px/1.3 var(--font-heading); }
.mv-seqh span { font: 500 14px/1.4 var(--font-text); color: var(--on-accent-muted); }
.mv-frames { display: flex; flex-wrap: wrap; gap: 24px; }
.mv-f { margin: 0; width: 340px; display: flex; flex-direction: column; gap: 10px; }
.mv-f figcaption { font: 400 13px/1.45 var(--font-text); color: var(--on-accent-muted); }
.mv-f figcaption b { display: block; font: 600 13px/1.4 var(--font-text); color: var(--on-accent); font-variant-numeric: tabular-nums; }
.mv-scr { position: relative; width: 340px; height: 191px; border-radius: 12px; overflow: hidden; background: #000; box-shadow: 0 0 0 1px var(--glass-edge); }
.mv-scr > .mv-mini.mv-mini { position: absolute; left: 0; top: 0; width: 1600px; height: 900px; min-height: 0; transform: scale(.2125); transform-origin: 0 0; }
.mv-tag { position: absolute; z-index: 9; top: 8px; right: 8px; padding: 2px 8px; border-radius: 999px; background: #0b0b0ecc; font: 600 12px/18px var(--font-text); color: var(--on-accent); }
.mv-tag i { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--brand-red); margin-right: 6px; vertical-align: 1px; }
.mv-click { position: absolute; z-index: 9; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; border: 2px solid #fff; box-shadow: 0 0 0 4px #ffffff40, 0 2px 8px #000a; }
/* variáveis de estado nas telas em miniatura */
.mv-mini > .dk-art { opacity: var(--art-op, 1); }
.mv-mini > .mv-art2.mv-art2 { position: absolute; inset: 0; padding: 0; min-height: 0; z-index: 0; opacity: var(--art2-op, 0); }
.mv-mini .dk-top ~ *, .mv-mini > .ob2-col { opacity: var(--pg-op, 1); translate: var(--pg-x, 0) 0; }
.mv-mini .dk-panel { opacity: var(--list-op, 1); }
.mv-mini .dk-panel ~ * { opacity: var(--main-op, 1); translate: 0 var(--main-y, 0); }
.mv-mini .dk-play { transform: scale(var(--play-s, 1)); }
.mv-mini.mv-layer { background: transparent; }
.mv-mini.mv-layer > .dk-art, .mv-mini.mv-layer > .gd-scrim, .mv-mini.mv-layer > .ob2-bg, .mv-mini.mv-layer > .ob2-wall { display: none; }
.mv-mini.mv-layer .dk-top, .mv-mini.mv-layer > .ob2-top { visibility: hidden; }
.mv-mini.mv-noul .dk-guia.dk-current::after { display: none; }
.mv-uline { position: absolute; z-index: 8; top: 61px; height: 2px; border-radius: 1px; background: var(--on-accent); }
.mv-pill { position: absolute; z-index: 3; border-radius: 999px; background: linear-gradient(180deg, var(--glass-item-highlight) 0%, #ffffff0a 60%), var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge); }
.mv-mini > .mv-scrim.mv-scrim { position: absolute; inset: 0; z-index: 5; background: #0b0b0e; opacity: var(--scrim-op, .6); }
.mv-mini > .mv-ov.mv-ov { position: absolute; inset: 0; z-index: 6; display: flex; align-items: center; justify-content: center; }
.mv-dlg { opacity: var(--dlg-op, 1); transform: translateY(var(--dlg-y, 0)) scale(var(--dlg-s, 1)); filter: blur(var(--dlg-b, 0)); }
.mv-mini .dk-panel-side { opacity: var(--side-op, 1); translate: var(--side-x, 0) 0; }
.mv-mini > div[style*="z-index:3"] { opacity: var(--side-scrim, 1); }
.mv-mini > .mv-menu.mv-menu { position: absolute; z-index: 6; transform-origin: 0 0; opacity: var(--menu-op, 1); transform: scale(var(--menu-s, 1)); }
.mv-mini > .mv-toast.mv-toast { position: absolute; z-index: 6; left: 0; right: 0; bottom: 48px; display: flex; justify-content: center; opacity: var(--toast-op, 1); translate: 0 var(--toast-y, 0); }
.mv-mini > .mv-tip.mv-tip { position: absolute; z-index: 6; opacity: var(--tip-op, 1); }
.mv-tipbox { padding: 8px 12px; border-radius: 10px; background: #0b0b0ef0; border: 1px solid var(--glass-edge); font: 500 15px/1.3 var(--font-text); color: var(--on-accent); white-space: nowrap; }
.mv-mini .gd-cover { opacity: var(--cov-op, 1); }
.mv-mini .mv-later { opacity: var(--late-op, 1); }
/* linha do tempo */
.mv-tl { display: grid; grid-template-columns: 260px 1fr; column-gap: 24px; row-gap: 12px; align-items: center; }
.mv-tl-l b { display: block; font: 600 13px/1.35 var(--font-text); color: var(--on-accent); }
.mv-tl-l span { display: block; font: 400 12px/1.4 var(--font-text); color: var(--on-accent-muted); font-variant-numeric: tabular-nums; }
.mv-track { position: relative; height: 10px; border-radius: 5px; background: #ffffff0f; }
.mv-track i { position: absolute; top: 0; bottom: 0; border-radius: 5px; left: var(--s); width: var(--w); min-width: 4px; background: var(--k); }
.mv-k-in { --k: var(--success); } .mv-k-out { --k: var(--warning); } .mv-k-st { --k: #9aa3b5; } .mv-k-now { --k: var(--on-accent); }
.mv-axis { position: relative; height: 18px; white-space: nowrap; font: 500 12px/18px var(--font-text); color: var(--on-accent-muted); font-variant-numeric: tabular-nums; }
.mv-axis span { position: absolute; transform: translateX(-50%); }
.mv-axis span:first-child { transform: none; } .mv-axis span:last-child { transform: translateX(-100%); }
.mv-legend { display: flex; flex-wrap: wrap; gap: 8px 20px; font: 500 12px/1.4 var(--font-text); color: var(--on-accent-muted); }
.mv-legend i { display: inline-block; width: 18px; height: 8px; border-radius: 4px; margin-right: 8px; vertical-align: 0; background: var(--k); }
.mv-rules { margin: 0; padding: 0 0 0 18px; columns: 2; column-gap: 40px; font: 400 14px/1.55 var(--font-text); color: var(--on-accent-muted); }
.mv-rules li { break-inside: avoid; margin-bottom: 6px; }
.mv-rules b { color: var(--on-accent); font-weight: 600; }
/* MovimentoBase */
.mv-grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.mv-curve { display: flex; flex-direction: column; gap: 10px; }
.mv-curves { display: flex; gap: 24px; flex-wrap: wrap; }
.mv-curves figure { margin: 0; display: flex; flex-direction: column; gap: 8px; width: 200px; font: 400 13px/1.45 var(--font-text); color: var(--on-accent-muted); }
.mv-curves figure b { color: var(--on-accent); font-weight: 600; display: block; }
.mv-curves svg { width: 200px; height: 140px; background: #ffffff08; border-radius: 12px; border: 1px solid var(--glass-edge); }
.mv-dur { display: grid; grid-template-columns: 150px 1fr 64px; gap: 10px 16px; align-items: center; font: 500 13px/1.35 var(--font-text); }
.mv-dur span:nth-child(3n+1) { color: var(--on-accent); }
.mv-dur span:nth-child(3n) { color: var(--on-accent-muted); text-align: right; font-variant-numeric: tabular-nums; }
.mv-dur i { display: block; height: 10px; border-radius: 5px; background: var(--on-accent-muted); width: var(--w); }
.mv-tbl { width: 100%; border-collapse: collapse; font: 400 13px/1.45 var(--font-text); }
.mv-tbl th { text-align: left; font-weight: 600; color: var(--on-accent); padding: 8px 12px 8px 0; border-bottom: 1px solid var(--glass-edge); }
.mv-tbl td { padding: 8px 12px 8px 0; color: var(--on-accent-muted); border-bottom: 1px solid var(--divider); vertical-align: top; }
.mv-tbl td:first-child { color: var(--on-accent); }
@media (prefers-reduced-motion: reduce) { .mv-live, .mv-live * { animation: none !important; } }
.mv-mini.mv-clear { background: transparent; }
.mv-mini.mv-noart > .dk-art { display: none; }
.mv-mini.mv-notop .dk-top { visibility: hidden; }
/* TelaJogoNaLoja › destaque (revisão UI UX Pro Max): preço é a segunda informação depois do nome; ritmo de 8 pt */
.lj-hero { gap: 0; }
.lj-hero .lj-back { height: 32px; padding: 0 12px 0 6px; gap: 2px; margin: 0 0 20px -6px; background: transparent; border: 0; box-shadow: none; color: var(--on-accent-muted); font: 600 14px/1 var(--font-text); }
.lj-hero .lj-back .dk-icon { width: 18px; height: 18px; }
.lj-hero .lj-back:hover { color: var(--on-accent); background: var(--glass-hover); }
.lj-hero .dk-badge { margin-bottom: 12px; }
.lj-hero .dk-display { margin: 0 0 16px; }
.lj-price { display: flex; flex-direction: column; gap: 8px; margin-bottom: 24px; }
.lj-price-row { display: flex; align-items: center; gap: 12px; }
.lj-price-off { height: 32px; min-width: 60px; font-size: 16px; border-radius: 8px; }
.lj-now { font: 700 32px/1 var(--font-heading); letter-spacing: -.01em; color: var(--on-accent); font-variant-numeric: tabular-nums; }
.lj-was { font: 500 16px/1 var(--font-text); color: var(--on-accent-subtle); text-decoration-thickness: 1.5px; align-self: flex-end; padding-bottom: 4px; }
.lj-price-sub { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 16px; font: 500 14px/1.4 var(--font-text); color: var(--on-accent-muted); }
.lj-price-sub > span:first-child { color: var(--on-accent); font-weight: 600; }
.lj-low { display: inline-flex; align-items: center; gap: 6px; }
.lj-low .dk-icon { width: 16px; height: 16px; color: var(--success); }
.lj-low b { color: var(--on-accent); font-weight: 600; }
.lj-meta { gap: 20px; margin-bottom: 28px; }
.lj-meta > div { gap: 6px; }
.lj-meta span { font-size: 13px; }
.lj-acts { margin: 0 0 16px; gap: 12px; }
.lj-wish { height: 52px; padding: 0 20px 0 16px; gap: 8px; border-radius: var(--radius-full); font-weight: 600; }
/* TelaLoja › destaque: mesmo bloco de preço e o mesmo ritmo de 8 pt da TelaJogoNaLoja */
.lj-hero .lj-desc { margin: 0 0 20px; max-width: 560px; }
.lj-hero .dk-affiliate { margin: 0 0 20px; }
.lj-hero .lj-carousel { margin: 0; }
.lj-hero .dk-pill-lg { height: 52px !important; padding: 0 20px !important; font-weight: 600; }
/* Vitrine: o destaque divide a altura com as fileiras; preço e loja numa linha só para caber em 900 */
.lj-hero:has(.lj-desc) .dk-display { font-size: 56px !important; margin-bottom: 12px; }
.lj-hero:has(.lj-desc) .lj-desc { margin-bottom: 16px; }
.lj-hero:has(.lj-desc) .lj-price { flex-direction: row; align-items: center; gap: 16px; margin-bottom: 20px; }
.lj-hero:has(.lj-desc) .lj-price-sub { padding-top: 6px; }
.lj-hero:has(.lj-desc) .lj-acts { margin-bottom: 12px; }
.lj-hero:has(.lj-desc) .dk-affiliate { margin-bottom: 16px; }
/* CampoDeSelecao: no desktop toda escolha de 1 entre N é um select (pílula + lista), nunca ‹ › nem ← → */
.st-select { position: relative; flex: none; }
.st-pill.st-sel { min-width: 120px; max-width: 280px; justify-content: space-between; gap: 12px; }
.st-pill.st-sel > b { font-weight: 600; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.st-pill.st-sel.dk-open { background: var(--settings-control-hover); box-shadow: inset 0 0 0 1px var(--focus-ring); }
.st-pill.st-sel.dk-ring { box-shadow: 0 0 0 3px var(--focus-glow), inset 0 0 0 1px var(--focus-ring); }
.st-pill.st-sel.dk-off-state { color: var(--on-accent-subtle); background: #ffffff0d; }
.st-list { position: absolute; z-index: 5; right: 0; top: calc(100% + 6px); min-width: 100%; width: max-content; max-width: 340px; padding: 6px;
  border-radius: var(--radius-control); background: var(--settings-surface); border: 1px solid var(--glass-edge-strong); box-shadow: var(--shadow-layer, 0 16px 40px #0009); }
.st-list .dk-menu-title { height: 28px; font-size: 12px; letter-spacing: .04em; text-transform: uppercase; }
.st-opt { height: 36px; padding: 0 12px 0 8px; border-radius: 10px; display: flex; align-items: center; gap: 8px; font: 500 14px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; cursor: pointer; }
.st-opt i { width: 18px; flex: none; display: inline-flex; justify-content: center; color: var(--on-accent); }
.st-opt i svg { width: 16px; height: 16px; }
.st-opt em { margin-left: auto; padding-left: 16px; font-style: normal; font-size: 12px; color: var(--on-accent-subtle); }
.st-opt.dk-hover { background: var(--settings-control-hover); }
.st-opt[aria-selected="true"] { font-weight: 600; }
.st-opt.dk-dis { color: var(--on-accent-subtle); cursor: default; }
/* variante de vidro (painel lateral e popups sobre a arte) */
.dk-row .st-pill.st-sel { margin-left: auto; height: 32px; background: var(--glass-control); border: 1px solid var(--glass-edge); box-shadow: none; }
/* BarraDaJanela: barra própria da janela (sem a moldura do Windows), como a do Discord, por cima da arte */
.wb-bar { position: absolute; z-index: 20; left: 0; right: 0; top: 0; height: 32px; display: flex; align-items: stretch;
  background: linear-gradient(180deg, var(--art-scrim-strong) 0%, var(--art-scrim-bottom) 60%, #0b0b0e00 100%); color: var(--on-accent); user-select: none; }
.wb-brand { display: flex; align-items: center; gap: 8px; padding: 0 12px 0 14px; }
.wb-brand .dk-logo { width: 47px; height: 18px; }
.wb-ctx { font: 500 12px/1 var(--font-text); color: var(--on-accent-muted); padding-left: 10px; border-left: 1px solid var(--divider); }
.wb-drag { flex: 1; }
.wb-btn { width: 46px; display: flex; align-items: center; justify-content: center; color: var(--on-accent-muted); cursor: default; }
.wb-btn svg { width: 10px; height: 10px; }
.wb-btn.dk-hover { background: var(--glass-hover); color: var(--on-accent); }
.wb-btn.dk-pressed { background: var(--glass-pressed); color: var(--on-accent); }
.wb-btn.wb-x.dk-hover { background: var(--window-close-hover); color: var(--on-accent); }
.wb-btn.wb-x.dk-pressed { background: color-mix(in srgb, var(--window-close-hover) 90%, #000); color: var(--on-accent); }
.wb-bar.wb-inactive .wb-btn, .wb-bar.wb-inactive .wb-ctx { color: var(--on-accent-subtle); }
.wb-bar.wb-inactive .dk-logo { opacity: .55; }
.wb-update { align-self: center; margin-right: 8px; height: 22px; padding: 0 10px; border-radius: var(--radius-full); display: inline-flex; align-items: center; gap: 6px;
  background: var(--glass-control); border: 1px solid var(--glass-edge); font: 600 12px/1 var(--font-text); color: var(--on-accent); }
.wb-update i { width: 6px; height: 6px; border-radius: 50%; background: var(--success); }
/* janela inteira na prévia */
.wb-win { position: relative; width: 1600px; height: 932px; border-radius: 8px; overflow: hidden; box-shadow: 0 0 0 1px #ffffff26, 0 30px 80px #000c; }
.wb-win > .dk-stage.wb-stage { position: absolute; inset: 0; min-height: 0; padding: 0; }
.wb-strip { position: relative; width: 760px; height: 32px; border-radius: 8px; overflow: hidden; background: var(--canvas); box-shadow: 0 0 0 1px var(--glass-edge); }
.wb-strip .wb-bar { background: linear-gradient(180deg, var(--art-scrim-strong), var(--art-scrim-bottom)); }
.wb-strip::before { content: ""; position: absolute; inset: 0; background: var(--art-img) center 20% / cover; }
.wb-cap { font: 500 13px/1.4 var(--font-text); color: var(--on-accent-muted); margin: 8px 0 0 2px; }
.wb-cap b { color: var(--on-accent); font-weight: 600; }
.wb-states { display: grid; grid-template-columns: repeat(2, 760px); gap: 24px 40px; }
.dk-stage > .wb-bar.wb-bar { position: absolute; z-index: 20; }
.wb-update { height: 24px; }
/* com a BarraDaJanela, a faixa de cima da arte escurece um pouco mais para a BarraSuperior manter 4,5:1 */
.dk-stage > .wb-topscrim.wb-topscrim { position: absolute; left: 0; right: 0; top: 0; height: 160px; z-index: 0; pointer-events: none;
  background: linear-gradient(180deg, var(--art-scrim-bottom) 0%, #0b0b0e00 100%); }
/* SeletorDeImagens: escolher capa, fundo, logo e ícone de um jogo (popup grande sobre a biblioteca) */
.dk-stage > .si-scrim.si-scrim { position: absolute; inset: 0; z-index: 5; background: #0b0b0eb3; }
.dk-stage > .si-wrap.si-wrap { position: absolute; inset: 0; z-index: 6; display: flex; align-items: center; justify-content: center; padding: 40px 48px; }
.si-dlg { width: 100%; max-width: 1440px; height: 100%; display: grid; grid-template-rows: auto auto 1fr; border-radius: var(--radius-card); overflow: hidden;
  background: linear-gradient(180deg, var(--glass-highlight) 0, #ffffff00 150px), var(--glass-panel-dense); border: 1px solid var(--glass-edge-strong);
  backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate)); box-shadow: var(--shadow-layer, 0 30px 80px #000a); }
.si-head { display: flex; align-items: center; gap: 16px; padding: 20px 20px 16px 24px; }
.si-head .dk-thumb { width: 44px; height: 44px; border-radius: var(--radius-thumb); flex: none; }
.si-titles { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.si-titles h2 { margin: 0; font: 700 22px/1.2 var(--font-heading); }
.si-titles span { font: 400 14px/1.3 var(--font-text); color: var(--on-accent-muted); }
.si-x { width: 40px; height: 40px; flex: none; }
.si-bar { display: flex; align-items: center; gap: 12px; padding: 0 24px 16px; border-bottom: 1px solid var(--divider); }
.si-bar .dk-tabs.dk-seg2 { margin: 0; }
.si-bar .dk-tab { padding: 0 16px; }
.si-sep { width: 1px; height: 24px; background: var(--divider); }
.si-bar .st-pill { height: 36px; }
.si-sp { flex: 1; }
.si-body { display: grid; grid-template-columns: 1fr 380px; min-height: 0; }
.si-gridwrap { min-height: 0; overflow: hidden; padding: 20px 24px; display: flex; flex-direction: column; gap: 12px; }
.si-count { font: 500 13px/1 var(--font-text); color: var(--on-accent-muted); display: flex; gap: 8px; align-items: center; }
.si-count b { color: var(--on-accent); font-weight: 600; }
.si-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(132px, 1fr)); gap: 16px; align-content: start; }
.si-tile { position: relative; aspect-ratio: 2 / 3; border-radius: 12px; overflow: hidden; cursor: pointer; background: var(--c, #222) ; box-shadow: inset 0 0 0 1px #ffffff14; }
.si-tile > i { position: absolute; inset: 0; background: var(--art-img) var(--x, 50%) var(--y, 30%) / var(--z, 320%) auto no-repeat; filter: var(--f, none); }
.si-tile > b { position: absolute; left: 10px; right: 10px; top: var(--ty, 12%); text-align: center; font: 800 18px/1 var(--font-heading); letter-spacing: -.01em; color: #fff; text-shadow: 0 2px 12px #000a; }
.si-tile.si-noimg { background: linear-gradient(160deg, var(--c1), var(--c2)); }
.si-tile.si-noimg > b { top: auto; bottom: 14px; font-size: 15px; }
