.si-ck svg { width: 14px; height: 14px; }
.si-now { position: absolute; top: 8px; left: 8px; height: 22px; padding: 0 8px; border-radius: var(--radius-full); background: #0b0b0ed9; font: 600 12px/22px var(--font-text); color: var(--on-accent); }
.si-tile.si-sk { background: #ffffff0f; animation: dk-pulse var(--tempo-pulso, 1600ms) ease-in-out infinite; box-shadow: none; }
.si-side { border-left: 1px solid var(--divider); padding: 20px 24px 24px; display: flex; flex-direction: column; gap: 16px; min-height: 0; background: #0b0b0e26; }
.si-side h3 { margin: 0; font: 600 13px/1 var(--font-text); letter-spacing: .04em; text-transform: uppercase; color: var(--on-accent-subtle); }
.si-big { align-self: center; width: 240px; aspect-ratio: 2 / 3; position: relative; border-radius: 14px; overflow: hidden; box-shadow: 0 16px 40px #0009, inset 0 0 0 1px #ffffff1f; }
.si-big > i { position: absolute; inset: 0; background: var(--art-img) var(--x) var(--y) / var(--z) auto no-repeat; }
.si-big > b { position: absolute; left: 12px; right: 12px; top: 12%; text-align: center; font: 800 30px/1 var(--font-heading); color: #fff; text-shadow: 0 2px 16px #000a; }
.si-meta { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; font: 400 13px/1.35 var(--font-text); }
.si-meta span { color: var(--on-accent-subtle); }
.si-meta b { font-weight: 500; color: var(--on-accent); }
.si-acts { margin-top: auto; display: flex; flex-direction: column; gap: 10px; }
.si-acts .dk-play { width: 100%; height: 52px; justify-content: center; }
.si-acts .si-row2 { display: flex; gap: 10px; }
.si-acts .si-row2 .dk-btn { flex: 1; justify-content: center; height: 44px; }
.si-hint { font: 400 12px/1.4 var(--font-text); color: var(--on-accent-subtle); text-align: center; }
.si-tile > i, .si-big > i { background: var(--art-img) var(--x, 50%) var(--y, 30%) / cover no-repeat; transform: scale(var(--s, 1.4)); transform-origin: var(--x, 50%) var(--y, 30%); }
.si-now { top: auto; bottom: 8px; }
/* FundoDoJogo: a arte de fundo no padrão da Steam (library_hero 3840 × 1240) e como ela se ajusta à janela */
.fj-file { position: relative; width: 1152px; height: 372px; border-radius: 12px; overflow: hidden; background: var(--hero) center / cover; box-shadow: 0 0 0 1px var(--glass-edge-strong); }
.fj-zone { position: absolute; top: 0; bottom: 0; border-left: 1px dashed #ffffffb3; border-right: 1px dashed #ffffffb3; }
.fj-zone.fj-safe { background: #ffffff0f; }
.fj-zone.fj-focus { border-color: var(--success); border-style: solid; background: #3ddc8414; }
.fj-zone span { position: absolute; left: 8px; padding: 2px 8px; border-radius: var(--radius-full); background: #0b0b0ed9; font: 600 12px/18px var(--font-text); color: var(--on-accent); white-space: nowrap; }
.fj-dim { position: absolute; right: 12px; bottom: 12px; padding: 4px 10px; border-radius: 8px; background: #0b0b0ed9; font: 600 13px/1.3 var(--font-text); }
.fj-wins { display: flex; gap: 24px; align-items: flex-end; flex-wrap: wrap; }
.fj-win { margin: 0; display: flex; flex-direction: column; gap: 8px; }
.fj-shot { position: relative; height: 150px; border-radius: 8px; overflow: hidden; background: var(--hero) no-repeat; box-shadow: 0 0 0 1px var(--glass-edge-strong); }
.fj-shot::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 40%; background: linear-gradient(90deg, var(--art-scrim-left), transparent); }
.fj-shot::after { content: ""; position: absolute; left: 4%; top: 14%; bottom: 8%; width: 22%; border-radius: 6px; background: var(--glass-panel); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.fj-win figcaption { font: 400 13px/1.4 var(--font-text); color: var(--on-accent-muted); }
.fj-win figcaption b { display: block; color: var(--on-accent); font-weight: 600; }
.fj-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.mv-mini > .dk-art { transform: scale(var(--art-s, 1)); filter: blur(var(--art-b, 0)); }
/* SeletorDeColecao: na aba Coleções, um select da largura do painel, com o mesmo raio do seletor de abas */
.dk-colsel { position: relative; margin: 6px 0 4px; }
.dk-colsel-btn { height: 40px; width: 100%; display: flex; align-items: center; gap: 10px; padding: 0 12px; border-radius: var(--radius-control);
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); font: 600 14px/1 var(--font-text); color: var(--on-accent); cursor: pointer; }
.dk-colsel-btn .dk-icon { width: 18px; height: 18px; color: var(--on-accent-muted); flex: none; }
.dk-colsel-btn b { flex: 1; min-width: 0; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dk-colsel-btn em { font: 500 13px/1 var(--font-text); font-style: normal; color: var(--on-accent-muted); white-space: nowrap; }
.dk-colsel-btn svg.ud { width: 10px; height: 14px; color: var(--on-accent-muted); flex: none; }
.dk-colsel-btn.dk-hover { background: var(--glass-hover); }
.dk-colsel-btn.dk-open { background: var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge); }
.dk-colsel .st-list { left: 0; right: 0; width: auto; max-width: none; background: var(--glass-solid); border-color: var(--glass-edge-strong); }
.dk-colsel .st-opt em { font-size: 13px; color: var(--on-accent-muted); }
.dk-colsel .st-opt .dk-icon { width: 16px; height: 16px; }
.dk-colsel .dk-menu-sep { margin: 4px 6px; }
/* TrocaDeJogo › troca do fundo em tamanho real: camadas só com opacidade e transform (sem animar filtro), arte nova sempre por cima */
.tj-wrap { display: grid; grid-template-columns: 1040px 1fr; gap: 28px; align-items: start; }
.tj-live { position: relative; width: 1040px; height: 520px; border-radius: 16px; overflow: hidden; background: var(--canvas); box-shadow: 0 0 0 1px var(--glass-edge-strong), 0 24px 60px #0008; isolation: isolate; }
.tj-art.tj-art { position: absolute; inset: 0; min-height: 0; padding: 0; display: block; overflow: hidden; will-change: opacity, transform; opacity: 0; }
.tj-art > i { position: absolute; inset: -2%; background: var(--art-img) 70% 25% / cover no-repeat; will-change: opacity; }
.tj-art > i.b { filter: blur(18px) saturate(1.2); transform: scale(1.06); }
.tj-art.g2 > i { background: radial-gradient(70% 90% at 72% 30%, #8a4fa6, transparent 70%), linear-gradient(160deg, #4a2b63, #1a0f22); }
.tj-glow { position: absolute; inset: 0; z-index: 5; pointer-events: none; mix-blend-mode: soft-light; opacity: 0; will-change: opacity; }
.tj-glow.g0 { background: radial-gradient(60% 80% at 75% 30%, #2a9d84, transparent 70%); }
.tj-glow.g1 { background: radial-gradient(60% 80% at 75% 30%, #3a6bd1, transparent 70%); }
.tj-glow.g2 { background: radial-gradient(60% 80% at 75% 30%, #b46fd6, transparent 70%); }
.tj-scrim { position: absolute; inset: 0; z-index: 6; background: linear-gradient(90deg, var(--canvas) 0%, var(--art-scrim-strong) 22%, var(--art-scrim-left) 42%, transparent 68%), linear-gradient(0deg, var(--art-scrim-bottom), transparent 40%); }
.tj-list { position: absolute; z-index: 7; left: 20px; top: 20px; bottom: 20px; width: 220px; padding: 8px; border-radius: var(--radius-card); background: var(--glass-panel); box-shadow: inset 0 0 0 1px var(--glass-edge); display: flex; flex-direction: column; gap: 4px; }
.tj-row { position: relative; height: 44px; display: flex; align-items: center; gap: 10px; padding: 0 8px; border-radius: var(--radius-row); font: 500 14px/1 var(--font-text); }
.tj-row > u { position: absolute; inset: 0; border-radius: inherit; background: var(--glass-selected); box-shadow: inset 0 0 0 1px var(--glass-item-edge); opacity: 0; will-change: opacity; }
.tj-row > span { position: relative; width: 28px; height: 28px; border-radius: 7px; background: linear-gradient(160deg, var(--t), var(--td)); flex: none; }
.tj-row > b { position: relative; font-weight: 500; }
.tj-hero { position: absolute; z-index: 7; left: 276px; bottom: 44px; width: 520px; height: 150px; }
.tj-txt { position: absolute; left: 0; bottom: 0; display: flex; flex-direction: column; gap: 10px; opacity: 0; will-change: opacity, transform; }
.tj-txt .dk-badge { align-self: flex-start; }
.tj-txt h4 { margin: 0; font: 700 48px/1 var(--font-heading); letter-spacing: -.02em; }
.tj-txt p { margin: 0; font: 500 14px/1.3 var(--font-text); color: var(--on-accent-muted); }
.tj-tag { position: absolute; z-index: 9; top: 12px; right: 12px; }
.tj-scrub { position: absolute; z-index: 9; left: 276px; right: 24px; bottom: 16px; height: 4px; border-radius: 2px; background: #ffffff1f; }
.tj-scrub > i { position: absolute; left: 0; top: 0; bottom: 0; width: 0; border-radius: 2px; background: var(--on-accent); }
.tj-notes { display: flex; flex-direction: column; gap: 14px; font: 400 14px/1.5 var(--font-text); color: var(--on-accent-muted); }
.tj-notes b { color: var(--on-accent); font-weight: 600; }
.tj-notes ol { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 8px; }
@media (prefers-reduced-motion: reduce) { .tj-art.g0, .tj-row.r0 > u, .tj-txt.t0, .tj-glow.g0 { opacity: 1 !important; } }
.tj-art.tj-art > i { position: absolute; inset: -2%; z-index: auto; }
/* CapaDoJogo: capa no padrão Steam 600 × 900 e onde ela aparece */
.cj-row { display: flex; gap: 32px; align-items: flex-end; flex-wrap: wrap; }
.cj-fig { margin: 0; display: flex; flex-direction: column; gap: 10px; }
.cj-cap { position: relative; border-radius: var(--radius-card); overflow: hidden; background: var(--art-img) 62% 20% / auto 100% no-repeat, var(--canvas); box-shadow: 0 0 0 1px var(--glass-edge-strong), 0 12px 30px #0008; }
.cj-cap > b { position: absolute; left: 8%; right: 8%; top: 7%; text-align: center; font: 800 var(--fs, 28px)/1 var(--font-heading); color: #fff; text-shadow: 0 2px 14px #000a; }
.cj-cap.cj-sq { border-radius: var(--radius-thumb); background-position: 62% 8%; background-size: auto 150%; }
.cj-safe { position: absolute; inset: 5%; border: 1px dashed #ffffffb3; border-radius: 10px; }
.cj-dim { position: absolute; right: 8px; bottom: 8px; padding: 3px 8px; border-radius: 8px; background: #0b0b0ed9; font: 600 12px/1.3 var(--font-text); }
.cj-fig figcaption { font: 400 13px/1.4 var(--font-text); color: var(--on-accent-muted); max-width: 260px; }
.cj-fig figcaption b { display: block; color: var(--on-accent); font-weight: 600; }
.cj-cap.cj-sm { border-radius: 10px; }
/* ControleDeslizante: volume e outros valores contínuos no desktop — arrastar, sem ‹ › */
.sl { display: inline-flex; align-items: center; gap: 10px; flex: none; color: var(--on-accent-muted); }
.sl > .sl-ic { width: 28px; height: 28px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.sl > .sl-ic svg { width: 18px; height: 18px; }
.sl > .sl-ic.dk-hover { background: var(--settings-control-hover); color: var(--on-accent); }
.sl-track { position: relative; width: 180px; height: 24px; display: flex; align-items: center; cursor: pointer; }
.sl-track::before { content: ""; position: absolute; left: 0; right: 0; height: 6px; border-radius: 3px; background: var(--settings-control); box-shadow: inset 0 0 0 1px #ffffff0f; }
.sl-fill { position: absolute; left: 0; height: 6px; border-radius: 3px; background: var(--on-accent); width: var(--v); }
.sl-knob { position: absolute; left: var(--v); width: 18px; height: 18px; margin-left: -9px; border-radius: 50%; background: var(--primary-top); box-shadow: 0 1px 4px #0008, 0 0 0 .5px #0003; transition: transform var(--tempo-hover, 180ms); }
.sl-val { min-width: 40px; text-align: right; font: 600 13px/1 var(--font-text); color: var(--on-accent); font-variant-numeric: tabular-nums; }
.sl.dk-hover .sl-knob, .sl.sl-drag .sl-knob { transform: scale(1.12); }
.sl.dk-ring .sl-knob { box-shadow: 0 0 0 4px var(--focus-glow), 0 0 0 1.5px var(--focus-ring), 0 1px 4px #0008; }
.sl-tip { position: absolute; left: var(--v); bottom: calc(100% + 6px); transform: translateX(-50%); padding: 4px 8px; border-radius: 8px; background: var(--glass-solid); border: 1px solid var(--glass-edge-strong); font: 600 12px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; }
.sl.sl-mute .sl-fill { background: var(--on-accent-subtle); }
.sl.sl-mute .sl-val { color: var(--on-accent-subtle); }
.sl.sl-off { opacity: .45; pointer-events: none; }
.sl-ticks { position: absolute; left: 0; right: 0; top: 19px; display: flex; justify-content: space-between; }
.sl-ticks i { width: 1px; height: 4px; background: #ffffff33; }
.sl.dk-ring.dk-ring.dk-ring { outline: none !important; box-shadow: none !important; background: none !important; background-image: none !important; }
/* TituloDoJogo: o título do Destaque é o logo do jogo (Steam library_logo, PNG transparente); sem logo, o texto display */
:root { --logo-hades: url("data:image/png;base64,"); }
.dk-titlelogo { margin: 0; line-height: 0; }
.dk-gamelogo { display: block; width: min(var(--logo-max-w, 520px), calc(var(--logo-max-h, 180px) * var(--ar, 3))); aspect-ratio: var(--ar, 3);
  background: var(--gl) left bottom / contain no-repeat; filter: drop-shadow(0 4px 20px #0b0b0eb3); }
.dk-hero:has(.dk-titlelogo) > .dk-badge { margin-bottom: 6px; }
.dk-small .dk-gamelogo { --logo-max-w: 380px; --logo-max-h: 130px; }
.tl-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.tl-case { margin: 0; display: flex; flex-direction: column; gap: 10px; }
.tl-scene { position: relative; height: 300px; border-radius: 14px; overflow: hidden; background: var(--art-img) 75% 25% / cover no-repeat; box-shadow: 0 0 0 1px var(--glass-edge-strong); }
.tl-scene.tl-dark { background: radial-gradient(60% 80% at 75% 30%, #1d2230, #0b0b0e 70%); }
.tl-scene.tl-azul { background: none; }
.tl-scene::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, var(--art-scrim-strong) 0%, var(--art-scrim-left) 45%, transparent 75%), linear-gradient(0deg, var(--art-scrim-bottom), transparent 50%); }
.tl-scene > .dk-hero { position: absolute; z-index: 1; left: 32px; bottom: 28px; --logo-max-w: 360px; --logo-max-h: 130px; }
.tl-scene .dk-display { font-size: 44px; }
.tl-case figcaption { font: 400 13px/1.45 var(--font-text); color: var(--on-accent-muted); }
.tl-case figcaption b { display: block; color: var(--on-accent); font-weight: 600; }
.tl-measure { position: absolute; z-index: 2; border: 1px dashed #ffffffb3; pointer-events: none; }
.tl-measure span { position: absolute; right: 0; top: -22px; padding: 2px 6px; border-radius: 6px; background: #0b0b0ed9; font: 600 12px/16px var(--font-text); white-space: nowrap; }
.tl-scene.tl-celeste { background: radial-gradient(70% 90% at 72% 30%, #8a4fa6, transparent 70%), linear-gradient(160deg, #4a2b63, #1a0f22); }

/* ListaDeJogos (app): linha de 44, passo de 50, sem ícone da loja, vaga fixa de 36 para o ▶ */
.dk-game + .dk-game { margin-top: 6px; }
.dk-game:not(:has(.dk-rowplay))::after { content: ""; width: 36px; height: 36px; flex: none; }
.dk-small .dk-game { height: 42px; } .dk-small .dk-thumb { width: 32px; height: 32px; }
.dk-iconbtn.dk-add .dk-icon { width: 18px; height: 18px; }
/* StorePill: a loja do jogo no canto superior direito do destaque */
.dk-storepill { position: absolute; z-index: 2; height: 28px; padding: 0 12px 0 8px; display: inline-flex; align-items: center; gap: 6px; border-radius: var(--radius-full);
  background: var(--glass-control); border: 1px solid var(--glass-edge-strong); font: 600 13px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; }
.dk-storepill .dk-icon { width: 16px; height: 16px; }
/* BarraSuperior: marca com hover (escala 1 → 1,04, opacidade 0,9 → 1) */
.dk-brand .dk-logo { opacity: .9; transition: transform var(--tempo-hover) var(--curva-entrada), opacity var(--tempo-hover) var(--curva-entrada); }
.dk-brand.dk-hover .dk-logo, .dk-brand.dk-open .dk-logo { opacity: 1; transform: scale(1.04); }
@media (prefers-reduced-motion: reduce) { .dk-brand .dk-logo { transform: none !important; } }

/* marca: tako-logo-horizontal em 2× (arquivo de 237 × 92), 46 de altura (38 na janela pequena) */
.dk-logo { width: 118px; height: 46px; }
.dk-small .dk-logo { width: 98px; height: 38px; }
/* DestaqueFases: fase 1 (destaque) e fase 2 (GameMore: informações completas) */
.df-hint { align-self: center; display: inline-flex; align-items: center; gap: 6px; font: 600 12px/1 var(--font-text); color: var(--on-accent-muted); margin-top: -12px; }
.df-hint .dk-icon { width: 14px; height: 14px; }
.df-back { align-self: center; height: 32px; padding: 0 14px 0 10px; border-radius: 16px; display: inline-flex; align-items: center; gap: 6px; flex: none;
  background: linear-gradient(180deg, var(--glass-highlight), #ffffff00 70%), var(--glass-panel); border: 1px solid var(--glass-edge); font: 600 13px/1 var(--font-text); color: var(--on-accent); }
.df-back .dk-icon { width: 16px; height: 16px; }
.df-more { flex: 1; min-height: 0; display: grid; grid-template-columns: 58fr 42fr; gap: 20px; overflow: hidden; }
.df-col { display: flex; flex-direction: column; gap: 20px; min-height: 0; }
.df-card { border-radius: var(--radius-card); padding: 24px; display: flex; flex-direction: column; gap: 12px; }
.df-card h2, .df-h { margin: 0; font: 700 20px/1.25 var(--font-heading); }
.df-card .dk-p { max-width: none; display: block; -webkit-line-clamp: unset; }
.df-row { min-height: 36px; display: grid; grid-template-columns: 16px 104px minmax(0, 1fr); column-gap: 12px; align-items: center; padding: 6px 0; border-top: 1px solid var(--divider); font: 500 13px/1.35 var(--font-text); }
.df-row:first-of-type { border-top: 0; }
.df-row .dk-icon { width: 16px; height: 16px; color: var(--on-accent-subtle); }
.df-row span { color: var(--on-accent-subtle); }
.df-row b { font-weight: 500; color: var(--on-accent); overflow-wrap: anywhere; }
.df-row.df-ses { grid-template-columns: 16px 72px minmax(0, 1fr) auto; }
.df-row.df-ses em { font-style: normal; color: var(--on-accent-muted); font-variant-numeric: tabular-nums; }
.df-shots { display: flex; gap: 12px; flex-wrap: wrap; }
.df-shots i { width: 256px; height: 144px; border-radius: 8px; background: var(--art-img) var(--x, 60%) var(--y, 30%) / 260% auto no-repeat; box-shadow: inset 0 0 0 1px #ffffff1a; }
.df-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.df-pair figure { margin: 0; display: flex; flex-direction: column; gap: 10px; }
.df-pair .mv-scr { width: 100%; height: auto; aspect-ratio: 16 / 9; }
.df-pair .mv-scr > .mv-mini.mv-mini { transform: scale(var(--sc)); }
.df-pair .wb-cap b { display: block; }
.dk-panel .dk-countact { gap: 2px !important; } /* texto começa na mesma coluna da miniatura e o último ícone centraliza com o ▶ da linha */
.dk-panel .dk-count { padding: 0 8px 0 9px; }

/* GameMore v2: números do jogo, requisitos, guia; rolagem sem desfoque ao vivo */
.df-more { align-content: start; -webkit-mask-image: linear-gradient(180deg, #000 calc(100% - 40px), transparent); mask-image: linear-gradient(180deg, #000 calc(100% - 40px), transparent); }
.df-more .dk-glass { backdrop-filter: none; -webkit-backdrop-filter: none; background: var(--glass-panel-dense); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.gm-tiles { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.gm-tile { border-radius: var(--radius-card); padding: 18px 20px; display: flex; flex-direction: column; gap: 12px; min-height: 148px; min-width: 0; }
.gm-th { display: flex; align-items: center; justify-content: space-between; gap: 8px; font: 600 12px/1 var(--font-text); letter-spacing: .06em; text-transform: uppercase; color: var(--on-accent-subtle); white-space: nowrap; min-height: 24px; }
.gm-src { display: inline-flex; align-items: center; min-height: 24px; font: 500 12px/1 var(--font-text); letter-spacing: 0; text-transform: none; color: var(--on-accent-muted); cursor: pointer; white-space: nowrap; }
.gm-mc { display: flex; align-items: center; gap: 14px; }
.gm-score { width: 52px; height: 52px; flex: none; border-radius: 12px; display: flex; align-items: center; justify-content: center; font: 800 24px/1 var(--font-heading); color: #0b0d10; background: var(--success); }
.gm-score.gm-mid { background: var(--warning); } .gm-score.gm-bad { background: var(--error); color: #fff; }
