.gm-note b { color: var(--on-accent-muted); font-weight: 600; }
.gm-big { font: 700 26px/1 var(--font-heading); color: var(--on-accent); font-variant-numeric: tabular-nums; white-space: nowrap; }
.gm-big small { font: 600 14px/1 var(--font-text); color: var(--on-accent-muted); margin-left: 6px; }
.gm-bar { position: relative; display: block; height: 6px; border-radius: 3px; background: #ffffff1f; flex: none; }
.gm-bar > i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 3px; background: var(--on-accent); }
.gm-bar.gm-range { background: linear-gradient(90deg, var(--success), var(--warning)); opacity: .85; }
.gm-bar > em { position: absolute; top: -4px; width: 4px; height: 14px; border-radius: 2px; background: var(--on-accent); box-shadow: 0 0 0 2px #0008; transform: translateX(-100%); }
.gm-hl { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.gm-hl div { display: flex; flex-direction: column; gap: 6px; font: 500 12px/1.2 var(--font-text); color: var(--on-accent-subtle); white-space: nowrap; }
.gm-hl b { font: 700 17px/1 var(--font-text); color: var(--on-accent); font-variant-numeric: tabular-nums; }
.gm-price { display: flex; justify-content: space-between; gap: 8px; font: 500 12px/1 var(--font-text); color: var(--on-accent-subtle); }
.gm-tag { align-self: flex-start; display: inline-flex; align-items: center; gap: 6px; min-height: 24px; padding: 4px 10px; border-radius: var(--radius-full); font: 600 12px/1.25 var(--font-text); background: #ffffff14; color: var(--on-accent); }
.gm-tag i { width: 7px; height: 7px; flex: none; border-radius: 50%; background: var(--success); } .gm-tag.gm-warn i { background: var(--warning); }
.gm-cardh { display: flex; align-items: center; gap: 12px; } .gm-cardh h2 { flex: 1; }
