.gm-seg span { height: 26px; padding: 0 12px; border-radius: var(--radius-full); display: inline-flex; align-items: center; font: 600 12px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; }
.gm-seg .dk-current { background: #ffffff26; color: var(--on-accent); }
.gm-req { display: grid; grid-template-columns: 112px minmax(0, 1fr) minmax(0, 1fr) 16px; column-gap: 12px; align-items: center; min-height: 36px; padding: 4px 0; border-top: 1px solid var(--divider); font: 500 13px/1.35 var(--font-text); }
.gm-req.gm-h { border-top: 0; min-height: 22px; font: 600 12px/1 var(--font-text); letter-spacing: .06em; text-transform: uppercase; }
.gm-req span { color: var(--on-accent-subtle); } .gm-req b { font-weight: 600; color: var(--on-accent); } .gm-req em { font-style: normal; color: var(--on-accent-muted); }
.gm-req .dk-icon { width: 16px; height: 16px; color: var(--success); } .gm-req .dk-icon.gm-w { color: var(--warning); }
.gm-open { align-self: flex-start; display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 14px 0 16px; border-radius: var(--radius-control); background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); font: 600 14px/1 var(--font-text); color: var(--on-accent); cursor: pointer; margin-top: 4px; }
.gm-open .dk-icon { width: 16px; height: 16px; }
.gm-ref { display: flex; flex-direction: column; gap: 20px; }
.gm-ref2 { display: grid; grid-template-columns: 58fr 42fr; gap: 20px; align-items: start; }
.gm-ref .df-card, .gm-ref .gm-tile { background: var(--glass-panel-dense); }

/* AtualizacaoDoApp */
.up-item { height: auto !important; min-height: 36px; padding-block: 8px !important; align-items: flex-start !important; }
.up-item > .dk-icon, .up-item > .up-spin { margin-top: 0; flex: none; }
.up-item > span:not(.up-spin) { display: flex; flex-direction: column; gap: 4px; line-height: 18px; }
.up-item small { font: 500 12px/1.3 var(--font-text); color: var(--on-accent-subtle); }
.up-item small b { color: var(--on-accent); font-weight: 600; cursor: pointer; }
.up-item.up-busy { color: var(--on-accent-muted); cursor: default; }
.up-item.up-ok .dk-icon { color: var(--success); } .up-item.up-err .dk-icon { color: var(--warning); }
.up-spin { width: 18px; height: 18px; border-radius: 50%; box-shadow: inset 0 0 0 2px #ffffff26; position: relative; display: inline-block; }
.up-spin::after { content: ""; position: absolute; inset: 0; border-radius: 50%; border: 2px solid transparent; border-top-color: var(--on-accent); animation: up-rot .8s linear infinite; }
@keyframes up-rot { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .up-spin::after { animation: none; border-right-color: var(--on-accent); } }
.up-flow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; align-items: start; }
.up-flow figure { margin: 0; display: flex; flex-direction: column; gap: 12px; }
.up-flow .dk-menu { width: 100%; box-sizing: border-box; }
.up-toastwrap { display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.up-toastwrap .dk-toast b { margin-left: 6px; padding: 0 6px; min-height: 28px; display: inline-flex; align-items: center; border-radius: 8px; font-weight: 700; cursor: pointer; }
.up-dlg { width: 500px; border-radius: var(--radius-card); padding: 24px; display: flex; flex-direction: column; gap: 18px; background: var(--glass-panel-dense); box-shadow: inset 0 0 0 1px var(--glass-edge-strong), var(--shadow-layer, 0 24px 60px #000a); }
.up-head { display: grid; grid-template-columns: 48px minmax(0, 1fr) 32px; gap: 14px; align-items: start; }
.up-ic { width: 48px; height: 48px; border-radius: 14px; display: flex; align-items: center; justify-content: center; background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); }
.up-ic .dk-icon { width: 22px; height: 22px; color: var(--on-accent); }
.up-head h2 { margin: 2px 0 6px; font: 700 20px/1.25 var(--font-heading); color: var(--on-accent); }
.up-head p { margin: 0; font: 500 13px/1.4 var(--font-text); color: var(--on-accent-muted); }
.up-head p b { color: var(--on-accent); font-weight: 600; }
.up-x { width: 32px; height: 32px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; background: var(--glass-control); color: var(--on-accent-muted); cursor: pointer; }
.up-x .dk-icon { width: 14px; height: 14px; }
.up-notes { border-radius: var(--radius-control); background: #ffffff0a; box-shadow: inset 0 0 0 1px var(--glass-edge); padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; }
.up-notes ul { margin: 0; padding: 0 0 0 18px; display: flex; flex-direction: column; gap: 6px; font: 500 14px/1.4 var(--font-text); color: var(--on-accent); }
.up-notes li::marker { color: var(--on-accent-subtle); }
.up-link { align-self: flex-start; display: inline-flex; align-items: center; gap: 6px; min-height: 24px; font: 600 13px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; }
.up-link .dk-icon { width: 14px; height: 14px; }
.up-prog { display: flex; flex-direction: column; gap: 8px; }
.up-bar { height: 6px; border-radius: 3px; background: #ffffff1f; overflow: hidden; } .up-bar i { display: block; height: 100%; border-radius: 3px; background: var(--on-accent); }
.up-prog span { display: flex; justify-content: space-between; font: 500 12px/1 var(--font-text); color: var(--on-accent-subtle); font-variant-numeric: tabular-nums; }
.up-warn { display: flex; gap: 10px; align-items: flex-start; font: 500 13px/1.4 var(--font-text); color: var(--on-accent); border-radius: var(--radius-control); padding: 10px 12px; background: color-mix(in srgb, var(--warning) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--warning) 40%, transparent); }
.up-warn .dk-icon { width: 18px; height: 18px; flex: none; color: var(--warning); }
.up-foot { display: flex; align-items: center; gap: 12px; }
.up-foot small { flex: 1; font: 500 12px/1.35 var(--font-text); color: var(--on-accent-subtle); }
.up-foot .dk-btn { height: 44px; }
.up-foot .dk-play { min-width: 0; height: 44px; padding: 0 22px; font-size: 15px; }
.up-dlgs { display: flex; gap: 32px; align-items: flex-start; }
.up-dlgs figure { margin: 0; display: flex; flex-direction: column; gap: 12px; }

/* Principal em cima, duas embaixo: a linha de baixo divide a largura da principal em partes iguais */
.dk-stack { display: flex; flex-direction: column; gap: 10px; }
.dk-stack > .dk-play, .dk-stack > .dk-btn { width: 100%; min-width: 0; height: 52px; justify-content: center; }
.dk-stack > .dk-stack-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.dk-stack > .dk-stack-row > * { min-width: 0; height: 44px; justify-content: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* StatusDoJogo no canto do destaque, ao lado da PilulaDaLoja */
.dk-corner { position: absolute; z-index: 2; display: flex; align-items: center; gap: 8px; }
.dk-corner > .dk-storepill { position: static; }
.dk-corner .dk-status { height: 28px; box-shadow: none; border: 1px solid var(--glass-edge-strong); }
.sd-hero { position: relative; width: 440px; height: 300px; border-radius: var(--radius-card); overflow: visible; }
.sd-hero > .dk-art { position: absolute; inset: 0; border-radius: inherit; overflow: hidden; }
.sd-hero .sd-wrap .st-list { left: auto; right: 0; }
/* StatusDoJogo + filtro ativo fixo */
.dk-status { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 9px 0 10px; border-radius: var(--radius-full);
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); font: 600 13px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; cursor: pointer; vertical-align: middle; }
.dk-status svg { width: 8px; height: 12px; color: var(--on-accent-muted); margin-left: 1px; }
.dk-status.dk-hover, .dk-status.dk-open { background: var(--glass-hover); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); }
.dk-status.dk-status-none { color: var(--on-accent-muted); font-weight: 500; }
.dk-sd { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--on-accent-subtle); }
.dk-sd-jogando { background: var(--success); } .dk-sd-quero { background: transparent; box-shadow: inset 0 0 0 1.5px var(--on-accent-muted); }
.dk-sd-pausado { background: var(--warning); } .dk-sd-zerado { background: var(--on-accent); } .dk-sd-abandonado { background: var(--on-accent-subtle); }
.dk-sd-none { background: transparent; box-shadow: inset 0 0 0 1.5px var(--on-accent-subtle); }
.dk-fbar { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 0 8px 4px; }
.dk-fchip { display: inline-flex; align-items: center; gap: 2px; height: 28px; padding: 0 2px 0 10px; border-radius: var(--radius-full);
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); font: 600 12px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; }
.dk-fchip-x { width: 24px; height: 24px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; color: var(--on-accent-muted); cursor: pointer; }
.dk-fchip-x svg { width: 9px; height: 9px; } .dk-fchip-x.dk-hover { background: var(--glass-hover); color: var(--on-accent); }
.dk-fclear { margin-left: auto; font: 600 12px/1 var(--font-text); color: var(--on-accent-muted); cursor: pointer; padding: 6px 4px; }
.sd-wrap { position: relative; display: inline-block; }
.sd-wrap .st-list { left: 0; right: auto; }
.st-opt .dk-sd { margin: 0 5px; }
.sd-cols { display: flex; gap: 40px; align-items: flex-start; padding: 36px; }
.sd-cap { font: 500 13px/1.45 var(--font-text); color: var(--on-accent-muted); margin: 12px 4px 0; max-width: 344px; }
.sd-cap b { color: var(--on-accent); font-weight: 600; }

/* Rodada 3: barra superior unificada com a barra da janela (borda a borda) */
div[style*="padding:12px 36px"] > .dk-top { margin: -12px -36px 0; width: calc(100% + 72px); flex: none; border-radius: 0; padding-left: 36px; padding-right: 0;
  border-width: 0 0 1px; border-style: solid; border-color: var(--glass-edge); box-shadow: none; }
div[style*="padding:12px 36px"] > .dk-top::before, div[style*="padding:12px 36px"] > .dk-top::after { border-radius: 0; }
.dk-top .wb-ctl { display: flex; align-self: stretch; flex: none; margin-left: 12px; }
.wb-c { width: 46px; display: inline-flex; align-items: center; justify-content: center; color: var(--on-accent-muted); cursor: default; }
.wb-c svg { width: 10px; height: 10px; }
.wb-c.dk-hover { background: var(--glass-hover); color: var(--on-accent); }
.wb-c.dk-pressed { background: var(--glass-pressed); color: var(--on-accent); }
.wb-c.wb-x.dk-hover { background: var(--window-close-hover); color: #fff; }
.wb-ctl.wb-inactive .wb-c { color: var(--on-accent-subtle); }
.dk-top .wb-update { margin: 0 4px 0 0; }
.dk-small div[style*="padding:12px 36px"] > .dk-top { margin: -10px -20px 0; width: calc(100% + 40px); padding-left: 20px; padding-right: 0; }
/* Metacritic na barra de números do destaque */
.dk-mc { width: 22px; height: 22px; flex: none; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; background: var(--success); color: #0b0d10; font: 800 11px/1 var(--font-text); font-variant-numeric: tabular-nums; }
.dk-mc.dk-mc-mid { background: var(--warning); } .dk-mc.dk-mc-bad { background: var(--error); color: #fff; }
.dk-sescard .dk-sesrow { min-height: 0; }
.dk-card.dk-sescard { flex: 1.1 !important; }
.dk-card:has(+ .dk-card + .dk-sescard) { flex: 1.25 !important; }
.wb-win.wb-win { height: 900px; }
.wb-strip.wb-strip2 { height: auto; overflow: hidden; background: none; box-shadow: 0 0 0 1px var(--glass-edge); border-radius: 8px; }
.wb-strip.wb-strip2::before { content: none; }
.wb-strip2 .dk-top { height: var(--topbar-height); }
.gm-tiles { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.gm-video { position: relative; aspect-ratio: 16 / 9; border-radius: 12px; overflow: hidden; display: flex; align-items: flex-end; padding: 14px; background: var(--art-img) 60% 25% / cover no-repeat; box-shadow: inset 0 0 0 1px #ffffff1a; cursor: pointer; }
.gm-video::before { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, #0000 45%, #000a); }
.gm-video > * { position: relative; }
.gm-video .dk-btn { height: 40px; padding: 0 16px 0 12px; gap: 8px; }
.gm-video .dk-btn .dk-icon { width: 16px; height: 16px; }
.gm-video em { margin-left: auto; font: 600 12px/1 var(--font-text); font-style: normal; color: var(--on-accent); background: #0009; padding: 5px 8px; border-radius: 6px; font-variant-numeric: tabular-nums; }

/* Rodada 4: busca fora da barra de cima */
.dk-panel > .dk-search-side { width: auto; height: 40px; flex: none; margin: 2px 0 0; }
.dk-panel > .dk-search-side .dk-key { margin-left: auto; }
.gd-bar { position: relative; }
.gd-bar > .gd-search { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 420px; z-index: 1; }
.dk-small .gd-bar > .gd-search { width: 280px; }

/* Perfil na barra de cima (como na Steam) e Tela cheia só com o ícone de controle */
.dk-me-chip { display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 10px 0 6px; border-radius: var(--radius-control); flex: none; cursor: pointer;
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); }
.dk-me-chip b { font: 600 14px/1 var(--font-text); color: var(--on-accent); white-space: nowrap; max-width: 140px; overflow: hidden; text-overflow: ellipsis; }
.dk-me-chip .dk-chev { width: 12px; height: 12px; color: var(--on-accent-muted); }
.dk-me-chip.dk-hover, .dk-me-chip.dk-open { background: var(--glass-hover); }
.dk-top .dk-btn.dk-fsbtn { width: 40px; height: 40px; padding: 0; justify-content: center; flex: none; }
.dk-top .dk-btn.dk-fsbtn .dk-icon { width: 22px; height: 22px; }
.dk-small .dk-me-chip b { display: none; }

/* BarraLateralUnida (opção de Aparência): barra de cima inteira + lista colada à esquerda — um vidro só, em L, sem emenda */
.dk-unif .ul-shell { position: absolute; inset: 0; z-index: 1; pointer-events: none; background: var(--glass-panel);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate)); backdrop-filter: blur(var(--glass-blur)) saturate(var(--glass-saturate));
  clip-path: polygon(0 0, 100% 0, 100% var(--topbar-height), 380px var(--topbar-height), 380px 100%, 0 100%); }
.dk-unif div[style*="padding:12px 36px"] > .dk-top, .dk-unif .dk-panel { background: none !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; border-color: transparent !important; box-shadow: none !important; }
.dk-unif div[style*="padding:12px 36px"] > .dk-top::before, .dk-unif div[style*="padding:12px 36px"] > .dk-top::after, .dk-unif .dk-panel::before, .dk-unif .dk-panel::after { display: none; }
.dk-unif .dk-panel { position: absolute; left: 0; top: var(--topbar-height); bottom: 0; width: 380px !important; z-index: 2; border: 0; border-radius: 0; padding: 28px 18px 16px 20px; gap: 12px; }
.dk-unif .dk-panel > .dk-count { margin-top: 2px; }
.dk-unif [style*="display:flex;gap:28px;flex:1"] > div:not(.dk-panel) { margin-left: 372px; }
.ul-cfg { width: 760px; }

/* NaoInstalados: seção por loja na lista e Instalar */
.ni-sep { display: flex; align-items: center; gap: 8px; margin: 10px 8px 2px; padding-top: 12px; border-top: 1px solid var(--divider); font: 700 12px/1 var(--font-text); letter-spacing: .08em; text-transform: uppercase; color: var(--on-accent-subtle); }
.ni-sep em { font-style: normal; font-weight: 600; letter-spacing: 0; }
.ni-grp { height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px 0 12px; border-radius: 10px; cursor: pointer; color: var(--on-accent-muted); font: 600 14px/1 var(--font-text); }
.ni-grp .dk-icon { width: 16px; height: 16px; flex: none; }
.ni-grp b { font-weight: 600; color: var(--on-accent); }
.ni-grp em { font-style: normal; font-size: 13px; color: var(--on-accent-subtle); margin-right: auto; }
.ni-grp:hover { background: var(--glass-hover); }
.ni-grp + .dk-game { margin-top: 2px; }
.dk-game.dk-missing .dk-thumb { opacity: .5; }
.ni-get { width: 36px; height: 36px; border-radius: 50%; flex: none; display: inline-flex; align-items: center; justify-content: center; color: var(--on-accent); opacity: 0; }
.ni-get.ni-show, .dk-game:hover .ni-get { opacity: 1; background: var(--glass-pressed); box-shadow: inset 0 0 0 1px var(--glass-edge-strong); }
.ni-get .dk-icon { width: 18px; height: 18px; }
.dk-game:has(.ni-get, .ni-prog)::after { display: none; }
.ni-prog { width: 36px; height: 36px; flex: none; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center;
  background: conic-gradient(var(--on-accent) calc(var(--p) * 1%), #ffffff26 0); -webkit-mask: radial-gradient(circle, transparent 14px, #000 14.5px); mask: radial-gradient(circle, transparent 14px, #000 14.5px); position: relative; }
.ni-prog i { position: absolute; inset: 0; display: none; }
.ni-hero { position: relative; width: 600px; height: 330px; border-radius: var(--radius-card); overflow: visible; }
.ni-hero > .dk-art { position: absolute; inset: 0; border-radius: inherit; overflow: hidden; background: linear-gradient(160deg, #2b4655, #0d1418 70%); }
.ni-heroin { position: absolute; left: 32px; bottom: 28px; display: flex; flex-direction: column; align-items: flex-start; gap: 14px; }
.ni-title { font: 700 44px/1.05 var(--font-heading); color: var(--on-accent); letter-spacing: -.02em; }
.ni-split { position: relative; display: inline-flex; gap: 2px; }
.ni-split .ni-main { min-width: 0; border-radius: var(--radius-full) 6px 6px var(--radius-full); padding: 0 24px 0 22px; gap: 10px; }
.ni-split .ni-main small { font: 600 13px/1 var(--font-text); opacity: .65; margin-left: 4px; }
.ni-split .ni-more { min-width: 0; width: 48px; padding: 0; justify-content: center; border-radius: 6px var(--radius-full) var(--radius-full) 6px; }
.ni-split .dk-icon { width: 20px; height: 20px; }
.ni-list { left: 0; right: auto; top: calc(100% + 8px); min-width: 260px; }
.ni-list .st-opt .dk-icon { width: 16px; height: 16px; color: var(--on-accent-muted); }
.ni-free { margin: 0; font: 500 13px/1.3 var(--font-text); color: var(--on-accent-muted); }

/* NaoInstalados na grade */
.ni-gsec { position: relative; padding: 0 36px 36px; display: flex; flex-direction: column; gap: 10px; }
.ni-gsec > .ni-sep { margin: 0 0 4px; }
.ni-gsec > .ni-grp { align-self: flex-start; min-width: 260px; }
.ni-ggrid { grid-template-columns: repeat(7, minmax(0, 1fr)); margin-bottom: 8px; }
.ni-gdl .dk-icon { margin-left: 0 !important; }
.ni-gprog { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: 64px; height: 64px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(circle, #000a 26px, transparent 26.5px), conic-gradient(var(--on-accent) calc(var(--p) * 1%), #ffffff33 0); }
