/* AtividadeNaBarra: atividades em segundo plano na barra de cima, antes do perfil */
.at-pill { display: inline-flex; align-items: center; gap: 10px; height: 40px; max-width: 340px; padding: 0 12px 0 11px; margin-right: 4px; border-radius: var(--radius-control); flex: none; cursor: pointer;
  background: var(--glass-control); box-shadow: inset 0 0 0 1px var(--glass-edge); color: var(--on-accent); }
