.at-txt small { font: 500 12px/1.1 var(--font-text); color: var(--on-accent-subtle); overflow: hidden; text-overflow: ellipsis; }
.at-txt, .at-txt > * { overflow: hidden; text-overflow: ellipsis; }
.at-spin { width: 16px; height: 16px; flex: none; }
