  -webkit-mask: radial-gradient(circle, transparent 6.5px, #000 7px); mask: radial-gradient(circle, transparent 6.5px, #000 7px); }
.at-ok > .dk-icon { color: var(--success); } .at-err > .dk-icon { color: var(--warning); }
.at-act { font: 700 12.5px/1 var(--font-text); padding: 6px 8px; margin: 0 -4px 0 2px; border-radius: 8px; background: #ffffff14; white-space: nowrap; }
