.at-upd .wb-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--success); flex: none; margin: 0 2px 0 4px; }
.at-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.at-grid .wb-strip { width: 100%; }
.at-multi figure { display: flex; flex-direction: column; gap: 10px; }
.at-strip { overflow: visible !important; }
.at-multi { display: flex; justify-content: flex-start; min-height: 480px; }
