.at-pop { position: absolute; right: 230px; top: calc(100% + 8px); width: 400px; z-index: 5; padding: 8px; border-radius: var(--radius-card);
  background: var(--glass-panel-dense); -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); box-shadow: inset 0 0 0 1px var(--glass-edge-strong), var(--shadow-layer); }
.at-poph { display: flex; align-items: baseline; justify-content: space-between; padding: 8px 10px 10px; }
.at-poph b { font: 700 15px/1 var(--font-heading); } .at-poph span { font: 500 12px/1 var(--font-text); color: var(--on-accent-subtle); }
.at-row { display: flex; align-items: center; gap: 12px; padding: 10px; border-radius: 10px; }
