.at-row > div { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.at-row b { font: 600 13.5px/1.2 var(--font-text); } .at-row span { font: 500 12px/1.3 var(--font-text); color: var(--on-accent-subtle); }
