.tk .app-body { flex: 1; min-height: 0; display: flex; position: relative; }
.tk .sidebar { width: var(--sbw); flex-shrink: 0; overflow: hidden; background: var(--g08, #080808); border-right: 1px solid var(--line); display: flex; flex-direction: column; padding: 14px 0 10px; position: relative; z-index: 5; transition: width .5s var(--ease), border-color .3s; }
